  (14, 'Пиромансер', 'Каждый раз, когда Пиромансер помещается на землю, нанеси 3 урона выбранному существу в этой линии. Потрать 1 действие >>> Перемести Пиромансера на пустую землю под твоим контролем.', 'существо', 1, 0, 8, false, '', '[]'::jsonb, 'исходники/карты/charlie_card_14.png', 'plains', false),
  (15, 'Некромансер', 'Каждый раз, когда существо под твоим контролем покидает игру, можешь переместить Некромансера на пустую землю того существа.', 'существо', 1, 1, 8, false, '', '[]'::jsonb, 'исходники/карты/charlie_card_15.png', 'plains', false),
  (17, 'Гидромансер', 'Когда Гидромансер вступает в игру, можешь найти Подмогу и сыграть ее бесплатно. Просмотренные карты смешай со своей колодой.', 'существо', 1, 3, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"play_for_free","target":"any","cost_filter":null,"source_text":"сыграть ее бесплатно"}],"conditions":[],"description":"можешь найти Подмогу и сыграть ее бесплатно","source_text":"Когда Гидромансер вступает в игру, можешь найти Подмогу и сыграть ее бесплатно"}]'::jsonb, 'исходники/карты/charlie_card_17.png', 'plains', false),
  (18, 'Хрономансер', 'Каждый раз когда Хрономансер меняет линию, получи 1 действие.', 'существо', 2, 3, 6, false, '', '[]'::jsonb, 'исходники/карты/charlie_card_18.png', 'plains', false),
  (19, 'Аэромансер', 'Когда Аэромансер вступает в игру, можешь поменять местами 2 существ выбранного игрока.', 'существо', 2, 3, 5, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"move","target":"each_creature","destination":"this_lane"}],"conditions":[],"description":"можешь поменять местами 2 существ выбранного игрока","source_text":"Когда Аэромансер вступает в игру, можешь поменять местами 2 существ выбранного игрока"}]'::jsonb, 'исходники/карты/charlie_card_19.png', 'plains', false),
  (2, 'Бочка', 'Каждая Бочка получает +1 ATK и +1 DEF за каждую другую Бочку в игре.', 'существо', 0, 1, 5, false, '', '[]'::jsonb, 'исходники/карты/charlie_card_2.png', 'rainbow', true),
  (20, 'Биомансер', 'Каждый раз когда существо под твоим контролем меняет линию, восстанови 2 урона у Биомансера.', 'существо', 1, 1, 8, false, '', '[]'::jsonb, 'исходники/карты/charlie_card_20.png', 'plains', false),
  (22, 'Просвещение', 'Посмотри 4 верхние карты в колоде выбранного игрока и верни их обратно в любом порядке. Затем тяни карту.', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/charlie_card_22.png', 'plains', false),
  (23, 'Отрази угрозу', 'Перемести 3 и менее урона с существа под твоим контролем на выбранное существо противника на этой линии.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[{"type":"verb","value":"Перемести"}],"description":"3 и менее урона с существа под твоим контролем на выбранное существо противника на этой линии","source_text":"Перемести 3 и менее урона с существа под твоим контролем на выбранное существо противника на этой линии"}]'::jsonb, 'исходники/карты/charlie_card_23.png', 'plains', false),
  (24, 'Цитадель с куполом', 'Твое существо на этой земле получает +2 DEF и не может быть поврежден заклинанием противника.', 'здание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/charlie_card_24.png', 'plains', false),
  (26, 'Сшитый ленивец', 'У каждого соседнего существа +1 ATK. Но если у Сшитого ленивца 4 уровня и более, то соседние существа получают +2 ATK.', 'существо', 2, 0, 8, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"соседние существа получают +2 ATK"}],"conditions":[{"type":"if","description":"у Сшитого ленивца 4 уровня и более"}],"description":"соседние существа получают +2 ATK","source_text":"если у Сшитого ленивца 4 уровня и более, то соседние существа получают +2 ATK"}]'::jsonb, 'исходники/карты/charlie_card_26.png', 'cute', false),
  (27, 'Набитый орангутан', 'Пока у Набитого орангутана 4 и более урона, его ATK удваивается.', 'существо', 2, 2, 8, false, '', '[{"trigger":"persistent","actions":[{"type":"passive","target":"none","effect":"его ATK удваивается"}],"conditions":[{"type":"while","description":"у Набитого орангутана 4 и более урона"}],"description":"его ATK удваивается","source_text":"Пока у Набитого орангутана 4 и более урона, его ATK удваивается"}]'::jsonb, 'исходники/карты/charlie_card_27.png', 'cute', false),
  (28, 'Выручка', 'Во время фазы сражения твоей и твоего партнёра, перед разъёмом каждой нанесён трон противнику, друзья наносят нанести 1 урон дыранову существу на 1 из своих линий.', 'special', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/charlie_card_28.png', 'cute', false),
  (2, 'Легкий жираф', 'Пока у Легкого жирафа 4 урона и более, он наносит урон непосредственно противнику вместо существа противника.', 'существо', 1, 1, 8, false, '', '[{"trigger":"persistent","actions":[{"type":"face_attack","source_text":"он наносит урон непосредственно противнику вместо существа противника"}],"conditions":[{"type":"while","description":"у Легкого жирафа 4 урона и более"}],"description":"он наносит урон непосредственно противнику вместо существа противника","source_text":"Пока у Легкого жирафа 4 урона и более, он наносит урон непосредственно противнику вместо существа противника"}]'::jsonb, 'исходники/карты/jake_2v2_card_13.png', 'cute', false),
  (3, 'Велик на двоих', 'Выбери существо под твоим контролем и верни его на руку владельцу. Выбери другого игрока. Он выбирает существо под его контролем и возвращает его на руку владельцу.', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Выбери","target":"none","effect":"существо под твоим контролем и верни его на руку владельцу"}],"conditions":[{"type":"verb","value":"Выбери"}],"description":"существо под твоим контролем и верни его на руку владельцу","source_text":"Выбери существо под твоим контролем и верни его на руку владельцу"}]'::jsonb, 'исходники/карты/charlie_card_3.png', 'rainbow', true),
  (30, 'Лёгкий жираф', 'Пока у Лёгкого жирафа 4 урона и более, он наносит урон непосредственно противнику вместо существа противника.', 'существо', 1, 1, 8, false, '', '[{"trigger":"persistent","actions":[{"type":"face_attack","source_text":"он наносит урон непосредственно противнику вместо существа противника"}],"conditions":[{"type":"while","description":"у Лёгкого жирафа 4 урона и более"}],"description":"он наносит урон непосредственно противнику вместо существа противника","source_text":"Пока у Лёгкого жирафа 4 урона и более, он наносит урон непосредственно противнику вместо существа противника"}]'::jsonb, 'исходники/карты/charlie_card_30.png', 'cute', false),
  (31, 'Очаровательный кролик', 'Если в начале твоего хода у Милашки коалы 4 урона и более, наноси 3 урона выбранному противнику.', 'существо', 1, 0, 8, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"passive","target":"none","effect":"в начале твоего хода у Милашки коалы 4 урона и более, наноси 3 урона выбранному противнику"}],"conditions":[],"description":"в начале твоего хода у Милашки коалы 4 урона и более, наноси 3 урона выбранному противнику","source_text":"в начале твоего хода у Милашки коалы 4 урона и более, наноси 3 урона выбранному противнику"},{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"наноси 3 урона выбранному противнику"}],"conditions":[{"type":"if","description":"в начале твоего хода у Милашки коалы 4 урона и более"}],"description":"наноси 3 урона выбранному противнику","source_text":"Если в начале твоего хода у Милашки коалы 4 урона и более, наноси 3 урона выбранному противнику"}]'::jsonb, 'исходники/карты/charlie_card_31.png', 'cute', false),
  (33, 'Вязаный котенок', 'На Вязаного котенка действуют строения соседних земель.', 'существо', 2, 3, 7, false, '', '[]'::jsonb, 'исходники/карты/charlie_card_33.png', 'cute', false),
  (34, 'Пушистая лиса', 'Пока у Пушистой лисы 4 и более урона, она игнорирует первые 2 урона нанесенные ей существами противника.', 'существо', 1, 2, 6, false, '', '[{"trigger":"persistent","actions":[{"type":"ignore_damage","amount":2,"source":"on_self","source_text":"она игнорирует первые 2 урона нанесенные ей существами противника"}],"conditions":[{"type":"while","description":"у Пушистой лисы 4 и более урона"}],"description":"она игнорирует первые 2 урона нанесенные ей существами противника","source_text":"Пока у Пушистой лисы 4 и более урона, она игнорирует первые 2 урона нанесенные ей существами противника"}]'::jsonb, 'исходники/карты/charlie_card_34.png', 'cute', false),
  (2, 'Привлекательный слон', 'Каждый раз когда Привлекательный слон становится целью заклинания противника, нанеси 2 урона выбранному существу противника.', 'существо', 2, 4, 4, false, '', '[]'::jsonb, 'исходники/карты/jake_2v2_card_12.png', 'cute', false),
  (37, 'Обнимашки', 'Уничтожь выбранное существо под твоим контролем, и затем уничтожь выбранное существо противника на этой линии.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"destroy","target":"chosen_creature","count":1},{"type":"destroy","target":"chosen_opponent_creature","count":1}],"conditions":[{"type":"verb","value":"Уничтожь"}],"description":"выбранное существо под твоим контролем, и затем уничтожь выбранное существо противника на этой линии","source_text":"Уничтожь выбранное существо под твоим контролем, и затем уничтожь выбранное существо противника на этой линии"}]'::jsonb, 'исходники/карты/charlie_card_37.png', 'cute', false),
  (38, 'Плюшевый', 'Выбери существо под своим контролем, нанеси ему урон равный его ATK и затем удвой его ATK в этом ходу.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Выбери","target":"none","effect":"существо под своим контролем, нанеси ему урон равный его ATK и затем удвой его ATK в этом ходу"}],"conditions":[{"type":"verb","value":"Выбери"}],"description":"существо под своим контролем, нанеси ему урон равный его ATK и затем удвой его ATK в этом ходу","source_text":"Выбери существо под своим контролем, нанеси ему урон равный его ATK и затем удвой его ATK в этом ходу"}]'::jsonb, 'исходники/карты/charlie_card_38.png', 'cute', false),
  (39, 'Шаровая бобовая бомба', 'ПРИЕМ >>> Восстанови или нанеси урон своему существу на этой земле, если у него 4 урона.', 'существо', 2, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"manual","target":"none","effect":"Восстанови или нанеси урон своему существу на этой земле, если у него 4 уро"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Восстанови или нанеси урон своему существу на этой земле, если у него 4 уро","source_text":"ПРИЕМ >>> Восстанови или нанеси урон своему существу на этой земле, если у него 4 уро"}]'::jsonb, 'исходники/карты/charlie_card_39.png', 'cute', false),
  (4, 'Связь', 'Впереди раз3 когда ты твой любой партнёр сыграете Радужное заклинание стоимостью 0 во время своего хода, другой партнёр может скопировать его и выбрать новую цель.', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/charlie_card_4.png', 'rainbow', false),
  (2, 'Ласковая овечка', 'Если в начале твоего хода у Ласковой овечки 4 уровня и более, нанеси 2 урона выбранному существу противника на этой линии.', 'существо', 1, 2, 7, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"deal_damage","target":"chosen_opponent_creature","amount":2,"pierce":false}],"conditions":[],"description":"в начале твоего хода у Ласковой овечки 4 уровня и более, нанеси 2 урона выбранному существу противника на этой линии","source_text":"в начале твоего хода у Ласковой овечки 4 уровня и более, нанеси 2 урона выбранному существу противника на этой линии"},{"trigger":"conditional","actions":[{"type":"deal_damage","target":"chosen_opponent_creature","amount":2,"pierce":false}],"conditions":[{"type":"if","description":"в начале твоего хода у Ласковой овечки 4 уровня и более"}],"description":"нанеси 2 урона выбранному существу противника на этой линии","source_text":"Если в начале твоего хода у Ласковой овечки 4 уровня и более, нанеси 2 урона выбранному существу противника на этой линии"}]'::jsonb, 'исходники/карты/jake_2v2_card_1.png', 'cute', false),
  (5, 'Торжество чар', 'Выбери существо и перемести на соседнюю землю под контролем его владельца. Как сделал это можешь отдать карту партнеру в руку.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[{"type":"verb","value":"Выбери"}],"description":"существо и перемести на соседнюю землю под контролем его владельца","source_text":"Выбери существо и перемести на соседнюю землю под контролем его владельца"}]'::jsonb, 'исходники/карты/charlie_card_5.png', 'rainbow', false),
  (6, 'Вклад', 'В начале фазы сражений твоей или твоего партнёра, если твой партнёр дыньчуй с более карт в этом ход, другой партнёр может тянуть карту.', 'special', 1, NULL, NULL, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"другой партнёр может тянуть карту"}],"conditions":[{"type":"if","description":"твой партнёр дыньчуй с более карт в этом ход"}],"description":"другой партнёр может тянуть карту","source_text":"если твой партнёр дыньчуй с более карт в этом ход, другой партнёр может тянуть карту"}]'::jsonb, 'исходники/карты/charlie_card_6.png', 'plains', false),
  (8, 'Облачная башня', 'Твое существо на этой земле не может стать целью заклинаний или способностей существ противника.
ПРИЕМ >>> Перемести Существо под твоим контролем на эту землю.', 'здание', 2, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Перемести Существо под твоим контролем на эту зем","source_text":"ПРИЕМ >>> Перемести Существо под твоим контролем на эту зем"}]'::jsonb, 'исходники/карты/charlie_card_8.png', 'plains', false),
  (1, 'Древний школяр', 'ПРИЕМ >>> Верни случайную Радужную карту из своей стопки сброса себе в руку. Если на этой линии контролируешь строение, получи 1 действие.', 'существо', 1, 1, 7, false, '', '[{"trigger":"manual","actions":[{"type":"return_from_discard","target":"chosen_discard","destination":"hand"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Верни случайную Радужную карту из своей стопки сброса себе в руку","source_text":"ПРИЕМ >>> Верни случайную Радужную карту из своей стопки сброса себе в руку"},{"trigger":"conditional","actions":[{"type":"gain_actions","target":"none","count":1}],"conditions":[{"type":"if","description":"на этой линии контролируешь строение"}],"description":"получи 1 действие","source_text":"Если на этой линии контролируешь строение, получи 1 действие"}]'::jsonb, 'исходники/карты/finn_card_1.png', 'plains', false),
  (10, 'Архитектор разума', 'Когда Архитектор разума вступает в игру, можешь повернуть примененное существо под твоим контролем.', 'существо', 1, 2, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"passive","target":"none","effect":"можешь повернуть примененное существо под твоим контролем"}],"conditions":[],"description":"можешь повернуть примененное существо под твоим контролем","source_text":"Когда Архитектор разума вступает в игру, можешь повернуть примененное существо под твоим контролем"}]'::jsonb, 'исходники/карты/finn_card_10.png', 'plains', false),
  (12, 'Кот-панк', 'Каждое существо, сменившее линию в этом ходу, получает +2 ATK в этом ходу.', 'существо', 1, 2, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"stat_buff","target":"this_creature","stat":"attack","amount":2,"duration":"this_turn"}],"conditions":[],"description":"получает +2 ATK в этом ходу","source_text":"получает +2 ATK в этом ходу"}]'::jsonb, 'исходники/карты/finn_card_12.png', 'plains', false),
  (14, 'Струзен Джинн', '+2 ATK каждому Применённому существу под твоим контролем.', 'существо', 2, 1, 11, false, '', '[]'::jsonb, 'исходники/карты/finn_card_14.png', 'plains', false),
  (16, 'Вождь Вайда', 'Вождь Вайда получает +2 ATK за каждое сыгранное тобой заклинание в этом ходу.', 'существо', 2, 2, 10, false, '', '[]'::jsonb, 'исходники/карты/finn_card_16.png', 'plains', false),
  (17, 'Мародер Вайда', 'Когда Мародер Вайда меняет линию во время хода, тяни карту.', 'существо', 2, 3, 9, false, '', '[]'::jsonb, 'исходники/карты/finn_card_17.png', 'plains', false),
  (19, 'Большой дух воина', 'Каждое соседнее существо получает +1 АТК.', 'существо', 1, 1, 9, false, '', '[{"trigger":"persistent","actions":[{"type":"stat_buff","target":"each_creature_adjacent","stat":"attack","amount":1,"duration":"persistent"}],"conditions":[],"description":"Каждое соседнее существо получает +1 АТК","source_text":"Каждое соседнее существо получает +1 АТК"}]'::jsonb, 'исходники/карты/finn_card_19.png', 'plains', false),
  (21, 'Уни-рыцарь', 'Потрать 1 действие >>> Выбери существо на этой линии, оно получает -10 ATK в этом ход.', 'существо', 1, 3, 4, false, '', '[]'::jsonb, 'исходники/карты/finn_card_21.png', 'plains', false),
