  (105, 'Апельсиновое желе', 'Если под твоим контролем 3 различных типа земель, то когда Апельсиновое желе выступает в игру нанеси 3 урона своему противнику.', 'существо', 1, 2, 6, false, '', '[{"trigger":"conditional","actions":[{"type":"deal_damage","target":"none","amount":3,"pierce":false}],"conditions":[{"type":"if","description":"под твоим контролем 3 различных типа земель"}],"description":"когда Апельсиновое желе выступает в игру нанеси 3 урона своему противнику","source_text":"Если под твоим контролем 3 различных типа земель, то когда Апельсиновое желе выступает в игру нанеси 3 урона своему противнику"}]'::jsonb, 'исходники/карты/ftg_card_105.png', 'swamp', false),
