  (107, 'Старик-разбойник', 'Когда Старик-разбойник вступает в игру, каждый игрок сбрасывает 2 карты.', 'существо', 2, 3, 8, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"discard_cards","target":"none","count":2,"source":"hand","random":false}],"conditions":[],"description":"каждый игрок сбрасывает 2 карты","source_text":"Когда Старик-разбойник вступает в игру, каждый игрок сбрасывает 2 карты"}]'::jsonb, 'исходники/карты/ftg_card_107.png', 'swamp', false),
  (108, 'Болотный глазастик', '+1 DEF за каждый различный тип земли под твоим контролем.', 'существо', 2, 4, 1, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_108.png', 'swamp', false),
  (109, 'Громила', 'ПРИЕМ >>> Выбери название карты. Выбери игрока. Удали из игры каждую карту с таким названием из стопки сброса выбранного игрока.', 'существо', 2, 1, 8, false, '', '[{"trigger":"manual","actions":[{"type":"manual","target":"none","effect":"Выбери название карты"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Выбери название карты","source_text":"ПРИЕМ >>> Выбери название карты"}]'::jsonb, 'исходники/карты/ftg_card_109.png', 'swamp', false),
  (110, 'Брекеты Огра', 'Восстанови себе 1 HP за каждые 5 карт в твоей стопке сброса.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Восстанови","target":"none","effect":"себе 1 HP за каждые 5 карт в твоей стопке сброса"}],"conditions":[{"type":"verb","value":"Восстанови"}],"description":"себе 1 HP за каждые 5 карт в твоей стопке сброса","source_text":"Восстанови себе 1 HP за каждые 5 карт в твоей стопке сброса"}]'::jsonb, 'исходники/карты/ftg_card_110.png', 'swamp', false),
  (111, 'Поднятие мертвых', 'Верни существо стоимостью 2 или менее из стопки сброса в игру.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"return_from_discard","target":"chosen_discard","destination":"this_lane"}],"conditions":[{"type":"verb","value":"Верни"}],"description":"существо стоимостью 2 или менее из стопки сброса в игру","source_text":"Верни существо стоимостью 2 или менее из стопки сброса в игру"}]'::jsonb, 'исходники/карты/ftg_card_111.png', 'swamp', false),
  (112, 'Волшебная лампа', 'Каждое твоё существо получает +2 ATK в этом ход, пока атакует Существо на Песчаной земле.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"persistent","actions":[{"type":"stat_buff","target":"each_creature","stat":"attack","amount":2,"duration":"this_turn"}],"conditions":[],"description":"Каждое твоё существо получает +2 ATK","source_text":"Каждое твоё существо получает +2 ATK"}]'::jsonb, 'исходники/карты/ftg_card_112.png', 'swamp', false),
