  (114, 'Призрачный маяк', 'Потрать 1 Действие >>> Выбранное Существо на этой линии получает +1 ATK в этот ход за каждые 5 карт в твоей стопке сброса.', 'здание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_114.png', 'swamp', false),
  (116, 'Теневая пирамида', 'ПРИЕМ >>> Тяни карту. Если ты контролируешь существо на этой линии, сбрось карту.', 'здание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"draw_cards","target":"none","count":1,"source":"deck"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Тяни карту","source_text":"ПРИЕМ >>> Тяни карту"},{"trigger":"conditional","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"if","description":"ты контролируешь существо на этой линии"}],"description":"сбрось карту","source_text":"Если ты контролируешь существо на этой линии, сбрось карту"}]'::jsonb, 'исходники/карты/ftg_card_116.png', 'swamp', false),
