  (14, 'Кольцо третьего глаза', 'Каждое твое существо получает +2 ATK в этот ход, пока атакует существо на Кукурузной земле.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"persistent","actions":[{"type":"stat_buff","target":"each_creature","stat":"attack","amount":2,"duration":"this_turn"}],"conditions":[],"description":"Каждое твое существо получает +2 ATK","source_text":"Каждое твое существо получает +2 ATK"}]'::jsonb, 'исходники/карты/ftg_card_14.png', 'plains', true),
