  (39, 'Золотой ниндзя', 'Когда золотой ниндзя вступает в игру, нанеси 1 урон выбранному существу за каждый различный тип земли под твоим контролем.', 'существо', 1, 2, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"deal_damage","target":"each_creature","amount":1,"pierce":false}],"conditions":[],"description":"нанеси 1 урон выбранному существу за каждый различный тип земли под твоим контролем","source_text":"Когда золотой ниндзя вступает в игру, нанеси 1 урон выбранному существу за каждый различный тип земли под твоим контролем"}]'::jsonb, 'исходники/карты/ftg_card_39.png', 'corn', false),
  (40, 'Итан Огонек', 'Когда Итан Огонек покидает игру, тяни 1 карту за каждую кукурузную землю под твоим контролем.', 'существо', 1, 0, 4, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_40.png', 'corn', false),
