  (42, 'Капитан Тако', 'Когда Капитан Тако вступает в игру, нанеси 1 урон каждому существу не на Кукурузной земле.', 'существо', 1, 1, 1, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"deal_damage","target":"each_creature_landscape","amount":1,"pierce":false}],"conditions":[],"description":"нанеси 1 урон каждому существу не на Кукурузной земле","source_text":"Когда Капитан Тако вступает в игру, нанеси 1 урон каждому существу не на Кукурузной земле"}]'::jsonb, 'исходники/карты/ftg_card_42.png', 'corn', false),
  (43, 'Яблочный страх', 'Земля Яблочного стража не может быть перевернута лицом вниз эффектами противника.', 'существо', 2, 3, 8, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_43.png', 'corn', false),
  (17, 'Стрелец Дэн', 'ПРИЕМ >>> Уничтожь выбранное строение на линии Стрельца Дэна.', 'существо', 2, 2, 6, false, '', '[{"trigger":"manual","actions":[{"type":"destroy","target":"this_lane","count":1}],"conditions":[{"type":"cost_actions","value":1}],"description":"Уничтожь выбранное строение на линии Стрельца Дэ","source_text":"ПРИЕМ >>> Уничтожь выбранное строение на линии Стрельца Дэ"}]'::jsonb, 'исходники/карты/jake_card_17.png', 'corn', false),
  (10, 'Кукурузные рыцари', 'Кукурузные рыцари получают +1 ATK и +2 DEF за каждое Кукурузное поле под твоим контролем.', 'существо', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/jake_card_10.png', 'corn', false),
  (48, 'Воскресная школа', 'Пока у тебя четное количество НР, твои существа на этой земле получают +2 АТК.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"persistent","actions":[{"type":"passive","target":"none","effect":"твои существа на этой земле получают +2 АТК"}],"conditions":[{"type":"while","description":"у тебя четное количество НР"}],"description":"твои существа на этой земле получают +2 АТК","source_text":"Пока у тебя четное количество НР, твои существа на этой земле получают +2 АТК"}]'::jsonb, 'исходники/карты/ftg_card_48.png', 'rainbow', false),
  (49, 'Гном-победитель', 'ПРИЕМ >>> Нанеси 1 урон каждому существу противника на Песчаных землях.', 'существо', 1, 1, 6, false, '', '[{"trigger":"manual","actions":[{"type":"deal_damage","target":"each_creature_opponent","amount":1,"pierce":false}],"conditions":[{"type":"cost_actions","value":1}],"description":"Нанеси 1 урон каждому существу противника на Песчаных земл","source_text":"ПРИЕМ >>> Нанеси 1 урон каждому существу противника на Песчаных земл"}]'::jsonb, 'исходники/карты/ftg_card_49.png', 'cute', false),
  (5, 'Дух ниндзя', 'Когда Дух ниндзя наносит урон противнику, этот противник не может играть заклинания во время своего следующего хода.', 'существо', 1, 2, 7, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_5.png', 'plains', false),
  (50, 'Клубничное желе', 'Если под твоим контролем 3 или более различных типов земель, то когда Клубничное желе вступает в игру, восстанови 4 урона с каждого существа под твоим контролем.', 'существо', 1, 2, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"heal","target":"each_creature_yours","amount":4,"cap":25}],"conditions":[],"description":"восстанови 4 урона с каждого существа под твоим контролем","source_text":"когда Клубничное желе вступает в игру, восстанови 4 урона с каждого существа под твоим контролем"},{"trigger":"conditional","actions":[{"type":"heal","target":"each_creature_yours","amount":4,"cap":25}],"conditions":[{"type":"if","description":"под твоим контролем 3 или более различных типов земель"}],"description":"когда Клубничное желе вступает в игру, восстанови 4 урона с каждого существа под твоим контролем","source_text":"Если под твоим контролем 3 или более различных типов земель, то когда Клубничное желе вступает в игру, восстанови 4 урона с каждого существа под твоим контролем"}]'::jsonb, 'исходники/карты/ftg_card_50.png', 'cute', false),
  (51, 'Хлопковый глазстик', '+1 DEF за каждый различный тип земель под твоим контролем.', 'существо', 2, 4, 1, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_51.png', 'cute', false),
  (5, 'Подушка боли', 'Бей её сильнее - ей всё равно. Подушка боли не может получить больше 4 урона за удар существа противника, зато магия наносит ей на 2 единицы урона больше.', 'существо', 2, 2, 10, false, '', '[]'::jsonb, 'исходники/карты/tree_trunks_card_5.png', 'cute', false),
  (53, 'Свиток свежего дыхания', 'Каждое твое существо получает +2 ATK, пока атакует существ на бесполезных болотах.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"persistent","actions":[{"type":"stat_buff","target":"each_creature","stat":"attack","amount":2,"duration":"persistent"}],"conditions":[],"description":"Каждое твое существо получает +2 ATK","source_text":"Каждое твое существо получает +2 ATK"}]'::jsonb, 'исходники/карты/ftg_card_53.png', 'cute', false),
  (54, 'Кондитерское колечко', 'Каждое твое существо получает +2 ATK, пока атакует существ на Кукурузной земле.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"persistent","actions":[{"type":"stat_buff","target":"each_creature","stat":"attack","amount":2,"duration":"persistent"}],"conditions":[],"description":"Каждое твое существо получает +2 ATK","source_text":"Каждое твое существо получает +2 ATK"}]'::jsonb, 'исходники/карты/ftg_card_54.png', 'cute', false),
