  (62, 'Красавчик Тимми', 'Красавчик Тимми получает +1 ATK пока атакует существ на песчаных землях.', 'существо', 2, 3, 6, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_62.png', 'rainbow', true),
  (35, 'Мисс Муми', 'В начале своего хода можешь вернуть Мисс Муми в руку владельцу. Если сделаешь это, выбранное Песчаное Существо под твоим контролем получает +1 DEF.', 'существо', 0, 1, 4, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"return_from_discard","target":"this_creature","destination":"hand"}],"conditions":[],"description":"В начале своего хода можешь вернуть Мисс Муми в руку владельцу","source_text":"В начале своего хода можешь вернуть Мисс Муми в руку владельцу"},{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"выбранное Песчаное Существо под твоим контролем получает +1 DEF"}],"conditions":[{"type":"if","description":"сделаешь это"}],"description":"выбранное Песчаное Существо под твоим контролем получает +1 DEF","source_text":"Если сделаешь это, выбранное Песчаное Существо под твоим контролем получает +1 DEF"}]'::jsonb, 'исходники/карты/lady_rainicorn_card_35.png', 'rainbow', true),
  (64, 'Квадурай', 'В начале своего хода нанеси 2 урона противнику с 4мя или более картами в руке.', 'существо', 0, 0, 6, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"deal_damage","target":"none","amount":2,"pierce":false}],"conditions":[],"description":"В начале своего хода нанеси 2 урона противнику с 4мя или более картами в руке","source_text":"В начале своего хода нанеси 2 урона противнику с 4мя или более картами в руке"}]'::jsonb, 'исходники/карты/ftg_card_64.png', 'rainbow', true),
  (65, 'Пощёчина ведьмы', 'Выбранный противник сбрасывает до 5 карт, затем получает 1 урон за каждую карту сброшенную таким образом.', 'заклинание', 2, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_65.png', 'rainbow', true),
