  (67, 'Музыкальный трон', 'Смени до 2х своих земель с теми которые сейчас не в игре.', 'здание', 0, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_67.png', 'rainbow', true),
  (68, 'Мастер маскировки', 'Каждое существо противника получает -1 ATK в этом ход.', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_68.png', 'rainbow', true),
  (69, 'Невероятное яйцо', 'Открой верхние 2 карты своей колоды. Можешь положить открытые Кукурузные карты себе в руку, остальные сбрось.', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Открой","target":"none","effect":"верхние 2 карты своей колоды"}],"conditions":[{"type":"verb","value":"Открой"}],"description":"верхние 2 карты своей колоды","source_text":"Открой верхние 2 карты своей колоды"}]'::jsonb, 'исходники/карты/ftg_card_69.png', 'rainbow', true),
