  (76, 'Лаймовое желе', 'Если под твоим контролем 3 и более различных типов земель, то когда Лаймовое желе вступает в игру, тяни 2 карты.', 'существо', 1, 2, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"draw_cards","target":"none","count":2,"source":"deck"}],"conditions":[],"description":"тяни 2 карты","source_text":"когда Лаймовое желе вступает в игру, тяни 2 карты"},{"trigger":"conditional","actions":[{"type":"draw_cards","target":"none","count":2,"source":"deck"}],"conditions":[{"type":"if","description":"под твоим контролем 3 и более различных типов земель"}],"description":"когда Лаймовое желе вступает в игру, тяни 2 карты","source_text":"Если под твоим контролем 3 и более различных типов земель, то когда Лаймовое желе вступает в игру, тяни 2 карты"}]'::jsonb, 'исходники/карты/ftg_card_76.png', 'sand', false),
  (4, 'Пляжная мумия', 'ПРИЕМ >>> Верни существо на соседней линии в руку владельцу.', 'существо', 1, 0, 7, false, '', '[{"trigger":"manual","actions":[{"type":"manual","target":"none","effect":"Верни существо на соседней линии в руку владель"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Верни существо на соседней линии в руку владель","source_text":"ПРИЕМ >>> Верни существо на соседней линии в руку владель"}]'::jsonb, 'исходники/карты/lady_rainicorn_card_4.png', 'sand', false),
