  (82, 'Зеленый король Вечеринок', 'Когда существо под твоим контролем покидает игру, восстанови 1 урон с Зеленого короля Вечеринок.', 'существо', 1, 1, 8, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_82.png', 'sand', false),
