  (84, 'Бриллиантовый Дэн', 'Когда Бриллиантовый Дэн покидает игру с Милой земли, верни его владельцу в руку.', 'существо', 1, 2, 2, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_84.png', 'sand', false),
  (35, 'Пескозавр рекс', '+2 ATK за каждую твою пустую землю.', 'существо', 2, 0, 9, false, '', '[]'::jsonb, 'исходники/карты/lemongrab_card_35.png', 'sand', true),
  (86, 'Мозговой смерч', 'Верни всех своих существ в игре себе в руку (включая украденных существ).', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Верни","target":"none","effect":"всех своих существ в игре себе в руку (включая украденных существ)"}],"conditions":[{"type":"verb","value":"Верни"}],"description":"всех своих существ в игре себе в руку (включая украденных существ)","source_text":"Верни всех своих существ в игре себе в руку (включая украденных существ)"}]'::jsonb, 'исходники/карты/ftg_card_86.png', 'sand', false),
  (87, 'Портал в никуда', 'Передвинь 1 существо противника на соседнюю пустую линию (на его стороне).', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_87.png', 'sand', false),
  (88, 'Портал антипризыва', 'Верни выбранное существо его владельцу в руку.', 'заклинание', 2, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Верни","target":"none","effect":"выбранное существо его владельцу в руку"}],"conditions":[{"type":"verb","value":"Верни"}],"description":"выбранное существо его владельцу в руку","source_text":"Верни выбранное существо его владельцу в руку"}]'::jsonb, 'исходники/карты/ftg_card_88.png', 'sand', false),
  (89, 'Счастливая монетка', 'Каждое твое существо получает +2 ATK, пока атакует существ на Голубых равнинах.', 'особая', 1, NULL, NULL, false, '', '[{"trigger":"persistent","actions":[{"type":"stat_buff","target":"each_creature","stat":"attack","amount":2,"duration":"persistent"}],"conditions":[],"description":"Каждое твое существо получает +2 ATK","source_text":"Каждое твое существо получает +2 ATK"}]'::jsonb, 'исходники/карты/ftg_card_89.png', 'sand', false),
  (9, 'Ледяной глазастик', '+1 DEF за каждый различный тип земли под твоим контролем.', 'существо', 2, 4, 1, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_9.png', 'plains', false),
  (90, 'Глаза змеи', 'Каждое твое существо получает +2 ATK, пока атакует существ на Бесполезных болотах.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"persistent","actions":[{"type":"stat_buff","target":"each_creature","stat":"attack","amount":2,"duration":"persistent"}],"conditions":[],"description":"Каждое твое существо получает +2 ATK","source_text":"Каждое твое существо получает +2 ATK"}]'::jsonb, 'исходники/карты/ftg_card_90.png', 'sand', false),
  (91, 'Песчаная пирамида', 'Потрать 2 Действия >>> Верни каждое существо на этой линии в руку своему владельцу. (Влияет на обоих игроков.)', 'здание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_91.png', 'sand', false),
  (92, 'Храм солнца', 'Когда на этой линии вступает в игру песчаное существо под твоим контролем, стоимостью 1 и более, можешь вернуть его на руку владельцу.', 'здание', 1, NULL, NULL, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"return_from_discard","target":"this_creature","destination":"hand"}],"conditions":[],"description":"песчаное существо под твоим контролем, стоимостью 1 и более, можешь вернуть его на руку владельцу","source_text":"Когда на этой линии вступает в игру песчаное существо под твоим контролем, стоимостью 1 и более, можешь вернуть его на руку владельцу"}]'::jsonb, 'исходники/карты/ftg_card_92.png', 'sand', false),
  (97, 'Черный паладин', '+1 ATK за каждую карту сброшенную игроками (включая тебя) с руки в этом ход.', 'существо', 1, 1, 7, false, '', '[]'::jsonb, 'исходники/карты/ftg_card_97.png', 'swamp', false),
  (98, 'Голубой тритон', 'ПРИЕМ >>> Тяни карту. Затем сбрось карту.', 'существо', 1, 2, 5, false, '', '[{"trigger":"manual","actions":[{"type":"draw_cards","target":"none","count":1,"source":"deck"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Тяни карту","source_text":"ПРИЕМ >>> Тяни карту"}]'::jsonb, 'исходники/карты/ftg_card_98.png', 'swamp', false),
  (99, 'Любимый чувачок', 'В начале своего хода посмотри верхнюю карту своей колоды. Можешь положить ее вниз своей колоды.', 'существо', 1, 1, 8, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"peek","count":1,"source":"deck","source_text":"В начале своего хода посмотри верхнюю карту своей колоды"}],"conditions":[],"description":"В начале своего хода посмотри верхнюю карту своей колоды","source_text":"В начале своего хода посмотри верхнюю карту своей колоды"}]'::jsonb, 'исходники/карты/ftg_card_99.png', 'swamp', false),
  (1, 'Ледяной лазутчик', 'Когда Ледяной лазутчик вступает в игру, заморозь его землю.', 'существо', 0, 1, 5, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"freeze_landscape","target":"chosen_landscape"}],"conditions":[],"description":"заморозь его землю","source_text":"Когда Ледяной лазутчик вступает в игру, заморозь его землю"}]'::jsonb, 'исходники/карты/grand_prix_card_1.png', 'rainbow', true),
  (10, 'Ледящее пение', 'Выбери и заморозь 1 землю у каждого игрока, затем тяни карту.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"freeze_landscape","target":"chosen_landscape"},{"type":"draw_cards","target":"none","count":1,"source":"deck"}],"conditions":[{"type":"verb","value":"Выбери"}],"description":"и заморозь 1 землю у каждого игрока, затем тяни карту","source_text":"Выбери и заморозь 1 землю у каждого игрока, затем тяни карту"}]'::jsonb, 'исходники/карты/grand_prix_card_10.png', 'ice', false),
  (11, 'Ледяной лимонад', 'Сосчитай количество земель с ледяными жетонами. Восстанови 1 урон с такого же количества дружественных существ.', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/grand_prix_card_11.png', 'ice', true),
  (12, 'Ультра пес', 'ПРИЕМ >>> Заморозь выбранную землю и существо на ней.', 'существо', 2, 3, 6, false, '', '[{"trigger":"manual","actions":[{"type":"freeze_landscape","target":"chosen_landscape"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Заморозь выбранную землю и существо на н","source_text":"ПРИЕМ >>> Заморозь выбранную землю и существо на н"}]'::jsonb, 'исходники/карты/grand_prix_card_12.png', 'ice', false),
  (13, 'Вафля в шоколаде', 'Если в начале твоей фазы сражения, на этой линии есть хотя бы один Ледяной жетон, нанеси 1 урона каждому существу под контролем выбранного игрока.', 'существо', 2, 2, 7, false, '', '[{"trigger":"conditional","actions":[{"type":"deal_damage","target":"each_creature","amount":1,"pierce":false}],"conditions":[{"type":"if","description":"в начале твоей фазы сражения"}],"description":"на этой линии есть хотя бы один Ледяной жетон, нанеси 1 урона каждому существу под контролем выбранного игрока","source_text":"Если в начале твоей фазы сражения, на этой линии есть хотя бы один Ледяной жетон, нанеси 1 урона каждому существу под контролем выбранного игрока"}]'::jsonb, 'исходники/карты/grand_prix_card_13.png', 'ice', false),
  (14, 'Банан в шоколаде', 'Если в начале твоей фазы сражения, на этой линии есть хотя бы один Ледяной жетон, нанеси 2 урона выбранному противнику.', 'существо', 1, 1, 7, false, '', '[{"trigger":"conditional","actions":[{"type":"deal_damage","target":"chosen_opponent","amount":2,"pierce":false}],"conditions":[{"type":"if","description":"в начале твоей фазы сражения"}],"description":"на этой линии есть хотя бы один Ледяной жетон, нанеси 2 урона выбранному противнику","source_text":"Если в начале твоей фазы сражения, на этой линии есть хотя бы один Ледяной жетон, нанеси 2 урона выбранному противнику"}]'::jsonb, 'исходники/карты/grand_prix_card_14.png', 'ice', false),
  (15, 'Сэндвич с мороженым', 'Потрать 1 Действие, ПРИЕМ >>> Выбери линию и заморозь обе земли на ней.', 'существо', 1, 2, 7, false, '', '[{"trigger":"manual","actions":[{"type":"freeze_landscape","target":"this_landscape_pair"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Выбери линию и заморозь обе земли на н","source_text":"Потрать 1 Действие, ПРИЕМ >>> Выбери линию и заморозь обе земли на н"}]'::jsonb, 'исходники/карты/grand_prix_card_15.png', 'ice', false),
  (16, 'Мятная мороженка', 'Пока на соседних линиях нет существ, Мятной мороженке нельзя нанести урон заклинаниями или способностями существ.', 'существо', 1, 3, 3, false, '', '[{"trigger":"persistent","actions":[{"type":"immunity","to":"damage_from_spells","source_text":"Мятной мороженке нельзя нанести урон заклинаниями или способностями существ"}],"conditions":[{"type":"while","description":"на соседних линиях нет существ"}],"description":"Мятной мороженке нельзя нанести урон заклинаниями или способностями существ","source_text":"Пока на соседних линиях нет существ, Мятной мороженке нельзя нанести урон заклинаниями или способностями существ"}]'::jsonb, 'исходники/карты/grand_prix_card_16.png', 'ice', false),
  (18, 'Mokkomem', 'Потрать 1 Действие, ПРИЕМ >>> Нанеси 2 урона выбранному существу. Если это существо погибло, заморозь землю под ним.', 'существо', 1, 0, 4, false, '', '[{"trigger":"manual","actions":[{"type":"deal_damage","target":"chosen_creature","amount":2,"pierce":false}],"conditions":[{"type":"cost_actions","value":1}],"description":"Нанеси 2 урона выбранному существу","source_text":"Потрать 1 Действие, ПРИЕМ >>> Нанеси 2 урона выбранному существу"},{"trigger":"conditional","actions":[{"type":"freeze_landscape","target":"chosen_landscape"}],"conditions":[{"type":"if","description":"это существо погибло"}],"description":"заморозь землю под ним","source_text":"Если это существо погибло, заморозь землю под ним"}]'::jsonb, 'исходники/карты/grand_prix_card_18.png', 'ice', false),
  (19, 'Замороженный патриот', 'Когда Замороженный патриот вступает в игру, можешь Заморозить Землю на этой линии.', 'существо', 1, 1, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"freeze_landscape","target":"chosen_landscape"}],"conditions":[],"description":"можешь Заморозить Землю на этой линии","source_text":"Когда Замороженный патриот вступает в игру, можешь Заморозить Землю на этой линии"}]'::jsonb, 'исходники/карты/grand_prix_card_19.png', 'ice', false),
  (2, 'Дай пять!', 'Восстанови или нанеси 1 урон выбранному существу. Как сделал это, можешь передать карту в руку своему партнёру.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"deal_damage","target":"chosen_creature","amount":1,"pierce":false}],"conditions":[{"type":"verb","value":"Восстанови"}],"description":"или нанеси 1 урон выбранному существу","source_text":"Восстанови или нанеси 1 урон выбранному существу"}]'::jsonb, 'исходники/карты/grand_prix_card_2.png', 'rainbow', true),
  (21, 'Коктейль', 'ПРИЦЕП >>> Перенеси Ледяной жетон с одной земли на другую землю.', 'существо', 1, 1, 8, false, '', '[]'::jsonb, 'исходники/карты/grand_prix_card_21.png', 'ice', false),
  (23, 'Мягкий рекрут', 'Когда Мягкий рекрут вступает на игру и у противника на этой линии нет существа под его контролем, получи 1 Действие.', 'существо', 1, 2, 5, false, '', '[]'::jsonb, 'исходники/карты/grand_prix_card_23.png', 'ice', false),
  (24, 'Товарищество', 'Каждый раз, когда существо противника наносит урон твоей команде, нанеси 1 урон команде противника.', 'special', 2, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/grand_prix_card_24.png', 'ice', false),
  (28, 'Песочный замок', 'Сбрось Песочный замок из игры >>> Возьми свое существо на этой земле в руку и сыграй его бесплатно.', 'building', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Сбрось","target":"none","effect":"Песочный замок из игры >>> Возьми свое существо на этой земле в руку и сыграй его бесплатно"}],"conditions":[{"type":"verb","value":"Сбрось"}],"description":"Песочный замок из игры >>> Возьми свое существо на этой земле в руку и сыграй его бесплатно","source_text":"Сбрось Песочный замок из игры >>> Возьми свое существо на этой земле в руку и сыграй его бесплатно"}]'::jsonb, 'исходники/карты/grand_prix_card_28.png', 'sand', false),
  (26, 'Остров голово-краба', 'Потрать 1 действие, ПРИЕМ >>> Если эта земля пустая, то открывай карты с верху своей колоды до тех пор, пока не найдешь Существо, сыграй его бесплатно на эту землю и замешай открытые карты обратно в свою колоду.', 'здание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"mill","count":1,"source":"deck","source_text":"то открывай карты с верху своей колоды до тех пор"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Если эта земля пустая, то открывай карты с верху своей колоды до тех пор, пока не найдешь Существо, сыграй его бесплатно на эту землю и замешай открытые карты обратно в свою коло","source_text":"Потрать 1 действие, ПРИЕМ >>> Если эта земля пустая, то открывай карты с верху своей колоды до тех пор, пока не найдешь Существо, сыграй его бесплатно на эту землю и замешай открытые карты обратно в свою коло"},{"trigger":"conditional","actions":[{"type":"mill","count":1,"source":"deck","source_text":"открывай карты с верху своей колоды до тех пор"}],"conditions":[{"type":"if","description":"эта земля пустая"}],"description":"открывай карты с верху своей колоды до тех пор, пока не найдешь Существо, сыграй его бесплатно на эту землю и замешай открытые карты обратно в свою колоду","source_text":"Если эта земля пустая, то открывай карты с верху своей колоды до тех пор, пока не найдешь Существо, сыграй его бесплатно на эту землю и замешай открытые карты обратно в свою колоду"},{"trigger":"persistent","actions":[{"type":"passive","target":"none","effect":"сыграй его бесплатно на эту землю и замешай открытые карты обратно в свою колоду"}],"conditions":[{"type":"while","description":"не найдешь Существо"}],"description":"сыграй его бесплатно на эту землю и замешай открытые карты обратно в свою колоду","source_text":"пока не найдешь Существо, сыграй его бесплатно на эту землю и замешай открытые карты обратно в свою колоду"}]'::jsonb, 'исходники/карты/grand_prix_card_26.png', 'sand', false),
  (27, 'Горячая подача', 'Уничтожь выбранное существо противника. Каждый противник тянет столько карт сколько стоило это существо.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"destroy","target":"chosen_opponent","count":1}],"conditions":[{"type":"verb","value":"Уничтожь"}],"description":"выбранное существо противника","source_text":"Уничтожь выбранное существо противника"}]'::jsonb, 'исходники/карты/grand_prix_card_27.png', 'sand', false),
  (29, 'Спасайся кто может!', 'Возьми выбранное существо под твоим контролем в руку, затем сыграй его бесплатно.', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/grand_prix_card_29.png', 'sand', false),
  (3, 'Дуэт', 'Восстанови 1 урон у Существа под твоим контролем и 1 урон у существа не под твоим контролем.', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"heal","target":"each_creature_yours","amount":1,"cap":25}],"conditions":[{"type":"verb","value":"Восстанови"}],"description":"1 урон у Существа под твоим контролем и 1 урон у существа не под твоим контролем","source_text":"Восстанови 1 урон у Существа под твоим контролем и 1 урон у существа не под твоим контролем"}]'::jsonb, 'исходники/карты/grand_prix_card_3.png', 'rainbow', true),
  (30, 'Лобстер-спасатель', 'Каждый раз когда существо вступает в игру во время твоего хода, ты должен восстановить 1 урон с другого существа.', 'существо', 2, 2, 9, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"passive","target":"none","effect":"во время твоего хода, ты должен восстановить 1 урон с другого существа"}],"conditions":[],"description":"во время твоего хода, ты должен восстановить 1 урон с другого существа","source_text":"когда существо вступает в игру во время твоего хода, ты должен восстановить 1 урон с другого существа"}]'::jsonb, 'исходники/карты/grand_prix_card_30.png', 'sand', false),
  (32, 'Сёрф-лобстер', '+1 ATK за каждую землю Бесполезных болот в игре.', 'существо', 2, 1, 7, false, '', '[]'::jsonb, 'исходники/карты/grand_prix_card_32.png', 'sand', false),
  (33, 'Отражающий камнекраб', 'Каждый раз когда Камнекраб регулировщик получает урон от существа, он наносит столько же урона этому же существу.', 'существо', 1, 1, 5, false, '', '[]'::jsonb, 'исходники/карты/grand_prix_card_33.png', 'sand', false),
  (34, 'Камнекраб регулировщик', 'Каждый раз когда Камнекраб регулировщик получает урон от существа, можешь переместить это существо на пустую соседнюю линию.', 'существо', 2, 2, 10, false, '', '[]'::jsonb, 'исходники/карты/grand_prix_card_34.png', 'sand', false),
  (36, 'Песочный краб пират', 'Когда песочный краб пират вступает в игру, можешь бесплатно сыграть существо стоимостью 1.', 'существо', 1, 2, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"play_for_free","target":"creature","cost_filter":null,"source_text":"можешь бесплатно сыграть существо стоимостью 1"}],"conditions":[],"description":"можешь бесплатно сыграть существо стоимостью 1","source_text":"Когда песочный краб пират вступает в игру, можешь бесплатно сыграть существо стоимостью 1"}]'::jsonb, 'исходники/карты/grand_prix_card_36.png', 'sand', false),
  (38, 'Ловкий песочный краб', 'Каждый раз когда во время твоего хода существо вступает в игру, можешь поменять их местами с Ловким песочным крабом.', 'существо', 1, 2, 7, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"passive","target":"none","effect":"можешь поменять их местами с Ловким песочным крабом"}],"conditions":[],"description":"можешь поменять их местами с Ловким песочным крабом","source_text":"когда во время твоего хода существо вступает в игру, можешь поменять их местами с Ловким песочным крабом"}]'::jsonb, 'исходники/карты/grand_prix_card_38.png', 'sand', false),
  (4, 'Пляжная Вечеринка', 'Открой 3 верхние карты своей колоды, вытяни одну, остальные сбрось. Как сделал это можешь вложить Пляжную Вечеринку в руку партнёра.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Открой","target":"none","effect":"3 верхние карты своей колоды, вытяни одну, остальные сбрось"}],"conditions":[{"type":"verb","value":"Открой"}],"description":"3 верхние карты своей колоды, вытяни одну, остальные сбрось","source_text":"Открой 3 верхние карты своей колоды, вытяни одну, остальные сбрось"}]'::jsonb, 'исходники/карты/grand_prix_card_4.png', 'rainbow', true),
  (40, 'Песочный краб рубака', 'Каждый раз когда во время твоего хода существо вступает в игру на соседнюю землю, Песочный краб рубака наносит 2 урона существу на этой линии.', 'существо', 2, 2, 8, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"deal_damage","target":"this_creature","amount":2,"pierce":false}],"conditions":[],"description":"на соседнюю землю, Песочный краб рубака наносит 2 урона существу на этой линии","source_text":"когда во время твоего хода существо вступает в игру на соседнюю землю, Песочный краб рубака наносит 2 урона существу на этой линии"}]'::jsonb, 'исходники/карты/grand_prix_card_40.png', 'sand', false),
  (5, 'Близняшки', 'Вытяни карту и открой ее. Выбранный игрок открывает верхнюю карту своей колоды. Если стоимость карт совпадает, выбранный игрок берет ее себе на руку.', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"conditional","actions":[{"type":"return_from_discard","target":"this_creature","destination":"hand"}],"conditions":[{"type":"if","description":"стоимость карт совпадает"}],"description":"выбранный игрок берет ее себе на руку","source_text":"Если стоимость карт совпадает, выбранный игрок берет ее себе на руку"}]'::jsonb, 'исходники/карты/grand_prix_card_5.png', 'rainbow', true),
  (6, 'Сотрудничество', 'В первые раз когда ты или твой партнёр сыграете Радужное заклинание, во время своего хода, другой партнёр может сыграть Радужное заклинание той же стоимости, бесплатно.', 'special', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/grand_prix_card_6.png', 'rainbow', true),
  (7, 'Бондарь', 'ПРИЕМ >>> Выбранное существо получает столько +ATK сколько стоят все карты партнерства под контролем твоей команды.', 'существо', 2, 3, 8, false, '', '[{"trigger":"manual","actions":[{"type":"manual","target":"none","effect":"Выбранное существо получает столько +ATK сколько стоят все карты партнерства под контролем твоей коман"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Выбранное существо получает столько +ATK сколько стоят все карты партнерства под контролем твоей коман","source_text":"ПРИЕМ >>> Выбранное существо получает столько +ATK сколько стоят все карты партнерства под контролем твоей коман"}]'::jsonb, 'исходники/карты/grand_prix_card_7.png', 'sand', false),
  (8, 'Подмога', 'В начале фазы сражения твоей или твоего партнера, если ты или партнёр сыграл существо стоимостью 2 и более в этот ход, другой партнёр может тянуть карту', 'special', 7, 2, 2, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"другой партнёр может тянуть карту"}],"conditions":[{"type":"if","description":"ты или партнёр сыграл существо стоимостью 2 и более в этот ход"}],"description":"другой партнёр может тянуть карту","source_text":"если ты или партнёр сыграл существо стоимостью 2 и более в этот ход, другой партнёр может тянуть карту"}]'::jsonb, 'исходники/карты/grand_prix_card_8.png', 'sand', false),
  (9, 'Ледяной банк', 'ПРИЕМ, Сними Ледяной жетон с земли на этой линии >>> Нанеси 3 урона выбранному противнику.', 'здание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/grand_prix_card_9.png', 'ice', false),
  (1, 'Крышесносяя кола', 'Каждое существо в игре получает +1 ATK в этом ходу (включая существ противника).', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"stat_buff","target":"this_creature","stat":"attack","amount":1,"duration":"this_turn"}],"conditions":[],"description":"получает +1 ATK в этом ходу","source_text":"получает +1 ATK в этом ходу"}]'::jsonb, 'исходники/карты/gunter_card_1.png', 'rainbow', true),
  (10, 'Пурга', 'Выбери линию и заморозь обе земли на ней.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"freeze_landscape","target":"this_landscape_pair"}],"conditions":[{"type":"verb","value":"Выбери"}],"description":"линию и заморозь обе земли на ней","source_text":"Выбери линию и заморозь обе земли на ней"}]'::jsonb, 'исходники/карты/gunter_card_10.png', 'ice', false),
  (12, 'Ледяной душегуб', 'Ледяной душегуб вступает в игру только на земли с ледяным жетоном.', 'существо', 1, 2, 6, false, '', '[]'::jsonb, 'исходники/карты/gunter_card_12.png', 'ice', false),
  (14, 'Ледяная снегобаба', 'Когда Ледяная снегобаба вступает в игру заморозь обе земли на ее линии.', 'существо', 2, 3, 5, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"freeze_landscape","target":"this_landscape_pair"}],"conditions":[],"description":"заморозь обе земли на ее линии","source_text":"Когда Ледяная снегобаба вступает в игру заморозь обе земли на ее линии"}]'::jsonb, 'исходники/карты/gunter_card_14.png', 'ice', false),
  (15, 'Ледяной гонщик', '+4 ATK, если обе земли на этой линии имеют Ледяные жетоны.', 'существо', 1, 2, 6, false, '', '[]'::jsonb, 'исходники/карты/gunter_card_15.png', 'ice', false),
  (16, 'Ледяной диверсант', 'Ледяной диверсант получает +1 АТК за каждую землю с Ледяным жетоном.', 'существо', 1, 1, 7, false, '', '[]'::jsonb, 'исходники/карты/gunter_card_16.png', 'ice', false),
  (18, 'Ледяной Штурмовик', 'Потрать 1 действие, ПРИЕМ >>> Заморозь выбранную землю.', 'существо', 1, 2, 7, false, '', '[{"trigger":"manual","actions":[{"type":"manual","target":"none","effect":"Заморозь выбранную зем"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Заморозь выбранную зем","source_text":"Потрать 1 действие, ПРИЕМ >>> Заморозь выбранную зем"}]'::jsonb, 'исходники/карты/gunter_card_18.png', 'ice', false),
  (2, 'Магазин для отдыха', 'ПРИЕМ >>> Перемести неактивное существо под твоим контролем на эту землю (если она пустая).', 'здание', 0, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Перемести неактивное существо под твоим контролем на эту землю (если она пуст","source_text":"ПРИЕМ >>> Перемести неактивное существо под твоим контролем на эту землю (если она пуст"}]'::jsonb, 'исходники/карты/gunter_card_2.png', 'rainbow', true),
  (20, 'Снежок', 'Удали Ледяной жетон с земли Снежка >>> Нанеси 3 урона выбранному существу.', 'существо', 1, 1, 8, false, '', '[]'::jsonb, 'исходники/карты/gunter_card_20.png', 'ice', false),
  (22, 'Морозильник', 'Когда Морозильник покидает игру, заморозь его землю.', 'существо', 2, 4, 7, false, '', '[]'::jsonb, 'исходники/карты/gunter_card_22.png', 'ice', false),
  (23, 'Заманчивое Спа', 'Если в начале твоей фазы Сражения, у тебя под контролем есть неактивное существо на этой земле, вытащи карту.', 'здание', 1, NULL, NULL, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"у тебя под контролем есть неактивное существо на этой земле, вытащи карту"}],"conditions":[{"type":"if","description":"в начале твоей фазы Сражения"}],"description":"у тебя под контролем есть неактивное существо на этой земле, вытащи карту","source_text":"Если в начале твоей фазы Сражения, у тебя под контролем есть неактивное существо на этой земле, вытащи карту"}]'::jsonb, 'исходники/карты/gunter_card_23.png', 'plains', false),
  (24, 'С добрым утром!', 'Подготовь каждое существо под твоим контролем.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Подготовь","target":"none","effect":"каждое существо под твоим контролем"}],"conditions":[{"type":"verb","value":"Подготовь"}],"description":"каждое существо под твоим контролем","source_text":"Подготовь каждое существо под твоим контролем"}]'::jsonb, 'исходники/карты/gunter_card_24.png', 'plains', false),
  (25, 'Мазокрака', 'Сыграй только, если под твоим контролем не более 1 существа и у тебя не более 15 HP. Перемести выбранное существо на выбранную линию под твоим контролем.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Сыграй","target":"none","effect":"только, если под твоим контролем не более 1 существа и у тебя не более 15 HP"}],"conditions":[{"type":"verb","value":"Сыграй"}],"description":"только, если под твоим контролем не более 1 существа и у тебя не более 15 HP","source_text":"Сыграй только, если под твоим контролем не более 1 существа и у тебя не более 15 HP"}]'::jsonb, 'исходники/карты/gunter_card_25.png', 'plains', false),
  (26, 'Последний раунд!', 'Выбранное существо под твоим контролем получает +2 АТК за каждое неактивное существо под твоим контролем (на момент вступления в игру).', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/gunter_card_26.png', 'plains', false),
  (28, 'Тонущий клирик', 'В начале своего хода перемести Тонущего клирика на пустую землю под твоим контролем. Если не смог, то сбрось его.', 'существо', 1, 3, 5, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[],"description":"В начале своего хода перемести Тонущего клирика на пустую землю под твоим контролем","source_text":"В начале своего хода перемести Тонущего клирика на пустую землю под твоим контролем"},{"trigger":"conditional","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"if","description":"не смог"}],"description":"сбрось его","source_text":"Если не смог, то сбрось его"}]'::jsonb, 'исходники/карты/gunter_card_28.png', 'plains', false),
  (3, 'Милый Оверлорг', 'Уничтожь любое число существ под твоим контролем. Тяни карту за каждого существа уничтоженного таким образом.', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"destroy","target":"none","count":1}],"conditions":[{"type":"verb","value":"Уничтожь"}],"description":"любое число существ под твоим контролем","source_text":"Уничтожь любое число существ под твоим контролем"}]'::jsonb, 'исходники/карты/gunter_card_3.png', 'rainbow', true),
  (31, 'Усталый библиотекарь', 'Усталый библиотекарь вступает в игру неактивным и не подготовлен в начале твоего хода. Всякий раз, когда он меняет линию, подготовь его.', 'существо', 1, 3, 4, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"passive","target":"none","effect":"в начале твоего хода"}],"conditions":[],"description":"в начале твоего хода","source_text":"в начале твоего хода"}]'::jsonb, 'исходники/карты/gunter_card_31.png', 'plains', false),
  (32, 'Заводской убийца', 'Уничтожь существо под твоим контролем, ПРИЕМ >>> Вытяни карту.', 'существо', 1, 2, 6, false, '', '[{"trigger":"manual","actions":[{"type":"manual","target":"none","effect":"Вытяни кар"}],"conditions":[{"type":"prerequisite","description":"Уничтожь существо под твоим контролем"}],"description":"Вытяни кар","source_text":"Уничтожь существо под твоим контролем, ПРИЕМ >>> Вытяни кар"},{"trigger":"manual","actions":[{"type":"destroy","target":"none","count":1},{"type":"draw_cards","target":"none","count":1,"source":"deck"}],"conditions":[{"type":"verb","value":"Уничтожь"}],"description":"существо под твоим контролем, ПРИЕМ >>> Вытяни карту","source_text":"Уничтожь существо под твоим контролем, ПРИЕМ >>> Вытяни карту"}]'::jsonb, 'исходники/карты/gunter_card_32.png', 'plains', false),
  (34, 'Усталый вомбат', 'В начале своего хода перемести Усталого вомбата на пустую землю под твоим контролем. Если не смог, то перемести на пустую землю твоего противника.', 'существо', 2, 4, 5, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[],"description":"В начале своего хода перемести Усталого вомбата на пустую землю под твоим контролем","source_text":"В начале своего хода перемести Усталого вомбата на пустую землю под твоим контролем"},{"trigger":"conditional","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[{"type":"if","description":"не смог"}],"description":"перемести на пустую землю твоего противника","source_text":"Если не смог, то перемести на пустую землю твоего противника"}]'::jsonb, 'исходники/карты/gunter_card_34.png', 'plains', false),
  (37, 'Усталый Воин', 'Усталый Воин вступает в игру неактивным и не подготовлен в начале твоего хода.

Всякий раз, когда он меняет линию, подготовь его.', 'существо', 2, 5, 6, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"passive","target":"none","effect":"в начале твоего хода"}],"conditions":[],"description":"в начале твоего хода","source_text":"в начале твоего хода"}]'::jsonb, 'исходники/карты/gunter_card_37.png', 'plains', false),
  (38, 'Предводитель Вайда', 'В начале своего хода перемести Предводителя Вайда на пустую землю под твоим контролем. Если не смог, то сбрось его.', 'существо', 1, 3, 4, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[],"description":"В начале своего хода перемести Предводителя Вайда на пустую землю под твоим контролем","source_text":"В начале своего хода перемести Предводителя Вайда на пустую землю под твоим контролем"},{"trigger":"conditional","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"if","description":"не смог"}],"description":"сбрось его","source_text":"Если не смог, то сбрось его"}]'::jsonb, 'исходники/карты/gunter_card_38.png', 'plains', false),
