  (40, 'Снежная полоса препятствий', 'ПРИЕМ >>> Заморозь обе земли на этой линии. Используй только если нет Ледяных жетонов в игре.', 'здание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"freeze_landscape","target":"this_landscape_pair"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Заморозь обе земли на этой линии","source_text":"ПРИЕМ >>> Заморозь обе земли на этой линии"}]'::jsonb, 'исходники/карты/gunter_card_40.png', 'rainbow', true),
