  (9, 'Плавучий Дворец Льда', 'Твое существо на этой земле получает +1 ATK во время твоего хода за каждую землю с Ледяным жетоном.', 'здание', 2, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/gunter_card_9.png', 'ice', false),
