  (16, 'Царственный олень', 'ПРИЕМ >>> Тяни карту за каждую землю с ледяным жетоном под контролем царебсов.', 'существо', 2, 4, 4, false, '', '[{"trigger":"manual","actions":[{"type":"draw_cards","target":"none","count":1,"source":"deck"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Тяни карту за каждую землю с ледяным жетоном под контролем царебс","source_text":"ПРИЕМ >>> Тяни карту за каждую землю с ледяным жетоном под контролем царебс"}]'::jsonb, 'исходники/карты/ice_king_card_16.png', 'ice', false),
