  (3, 'Бордер колли', 'ПРИЕМ >>> Перемести Бордер колли на любую свою пустую землю. Если эта земля заморожена, получи 1 Действие.', 'существо', 1, 1, 7, false, '', '[{"trigger":"manual","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Перемести Бордер колли на любую свою пустую землю","source_text":"ПРИЕМ >>> Перемести Бордер колли на любую свою пустую землю"},{"trigger":"conditional","actions":[{"type":"gain_actions","target":"none","count":1}],"conditions":[{"type":"if","description":"эта земля заморожена"}],"description":"получи 1 Действие","source_text":"Если эта земля заморожена, получи 1 Действие"}]'::jsonb, 'исходники/карты/ice_king_card_3.png', 'ice', false),
