  (38, 'Замороженное сердце', 'Нанеси 1 Урон выбранному существу. Если это существо на земле с ледяным жетоном, то вместо 1 нанеси 3 Урона.', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"conditional","actions":[{"type":"deal_damage","target":"none","amount":3,"pierce":false}],"conditions":[{"type":"if","description":"это существо на земле с ледяным жетоном"}],"description":"вместо 1 нанеси 3 Урона","source_text":"Если это существо на земле с ледяным жетоном, то вместо 1 нанеси 3 Урона"}]'::jsonb, 'исходники/карты/ice_king_card_38.png', 'rainbow', true),
