  (2, 'Обнимашный ёж', 'Пока у Обнимашного ежа 4 урона и более, он наносит урон непосредственно противнику вместо существа противника.', 'существо', 2, 3, 8, false, '', '[{"trigger":"persistent","actions":[{"type":"face_attack","source_text":"он наносит урон непосредственно противнику вместо существа противника"}],"conditions":[{"type":"while","description":"у Обнимашного ежа 4 урона и более"}],"description":"он наносит урон непосредственно противнику вместо существа противника","source_text":"Пока у Обнимашного ежа 4 урона и более, он наносит урон непосредственно противнику вместо существа противника"}]'::jsonb, 'исходники/карты/jake_2v2_card_15.png', 'cute', false),
  (2, 'Обнимашный еж', 'Пока у ∆Обнимашного ежа 4 урона и более, он наносит урон непосредственно противнику вместо существа противника.', 'существо', 2, 3, 8, false, '', '[{"trigger":"persistent","actions":[{"type":"face_attack","source_text":"он наносит урон непосредственно противнику вместо существа противника"}],"conditions":[{"type":"while","description":"у ∆Обнимашного ежа 4 урона и более"}],"description":"он наносит урон непосредственно противнику вместо существа противника","source_text":"Пока у ∆Обнимашного ежа 4 урона и более, он наносит урон непосредственно противнику вместо существа противника"}]'::jsonb, 'исходники/карты/jake_2v2_card_16.png', 'cute', false),
  (2, 'Дикий зебрарог', 'Когда Зеленый зебрарог атакует, нанеси 1 урон выбранному противнику.', 'существо', 1, 1, 6, false, '', '[{"trigger":"on_creature_attacks","actions":[{"type":"deal_damage","target":"chosen_opponent","amount":1,"pierce":false}],"conditions":[],"description":", нанеси 1 урон выбранному противнику","source_text":"Когда Зеленый зебрарог атакует, нанеси 1 урон выбранному противнику"}]'::jsonb, 'исходники/карты/jake_2v2_card_17.png', 'corn', true),
  (2, 'Бывалый зебрарог', 'Когда Бывалый зебрарог атакует, нанеси 2 урона выбранному противнику.', 'существо', 2, 2, 8, false, '', '[{"trigger":"on_creature_attacks","actions":[{"type":"deal_damage","target":"chosen_opponent","amount":2,"pierce":false}],"conditions":[],"description":", нанеси 2 урона выбранному противнику","source_text":"Когда Бывалый зебрарог атакует, нанеси 2 урона выбранному противнику"}]'::jsonb, 'исходники/карты/jake_2v2_card_18.png', 'corn', false),
  (2, 'Королевский малыш', 'Потрать 1 Действие, ПРИЕМ >>> Нанеси 1 урон выбранному существу за каждую Кукурузную землю под твоим контролем.', 'существо', 2, 2, 7, false, '', '[{"trigger":"manual","actions":[{"type":"deal_damage","target":"each_creature","amount":1,"pierce":false}],"conditions":[{"type":"cost_actions","value":1}],"description":"Нанеси 1 урон выбранному существу за каждую Кукурузную землю под твоим контрол","source_text":"Потрать 1 Действие, ПРИЕМ >>> Нанеси 1 урон выбранному существу за каждую Кукурузную землю под твоим контрол"}]'::jsonb, 'исходники/карты/jake_2v2_card_19.png', 'corn', false),
  (2, 'Защищенный зебрарог', 'Когда Защищенный зебрарог атакует, можешь восстановить 1 урон у соседнего существа.', 'существо', 1, 2, 6, false, '', '[{"trigger":"on_creature_attacks","actions":[{"type":"passive","target":"none","effect":", можешь восстановить 1 урон у соседнего существа"}],"conditions":[],"description":", можешь восстановить 1 урон у соседнего существа","source_text":"Когда Защищенный зебрарог атакует, можешь восстановить 1 урон у соседнего существа"}]'::jsonb, 'исходники/карты/jake_2v2_card_20.png', 'corn', false),
  (2, 'Защищенный зебрагон', 'Когда Защищенный зебрагон атакует, можешь восстановить 1 урон у соседнего существа.', 'существо', 1, 2, 6, false, '', '[{"trigger":"on_creature_attacks","actions":[{"type":"passive","target":"none","effect":", можешь восстановить 1 урон у соседнего существа"}],"conditions":[],"description":", можешь восстановить 1 урон у соседнего существа","source_text":"Когда Защищенный зебрагон атакует, можешь восстановить 1 урон у соседнего существа"}]'::jsonb, 'исходники/карты/jake_2v2_card_21.png', 'corn', false),
  (2, 'Шипастый зебрарог', 'Когда Шипастый зебрарог атакует, нанеси 1 урон каждому существу на соседней линии.', 'существо', 2, 2, 7, false, '', '[{"trigger":"on_creature_attacks","actions":[{"type":"deal_damage","target":"each_creature_adjacent","amount":1,"pierce":false}],"conditions":[],"description":", нанеси 1 урон каждому существу на соседней линии","source_text":"Когда Шипастый зебрарог атакует, нанеси 1 урон каждому существу на соседней линии"}]'::jsonb, 'исходники/карты/jake_2v2_card_22.png', 'corn', false),
  (2, 'Тренированный крылатый зебрарог', '+1 ATK за каждую Тимборн под контролем твоей команды. Если Тренированный крылатый зебрарог покидает игру во время твоей фазы сражения, можешь положить в свою руку.', 'существо', 2, 3, 7, false, '', '[{"trigger":"conditional","actions":[{"type":"draw_cards","target":"none","filter":"any","count":1,"source":"discard_pile"}],"conditions":[{"type":"if","description":"Тренированный крылатый зебрарог покидает игру во время твоей фазы сражения"}],"description":"можешь положить в свою руку","source_text":"Если Тренированный крылатый зебрарог покидает игру во время твоей фазы сражения, можешь положить в свою руку"}]'::jsonb, 'исходники/карты/jake_2v2_card_23.png', 'corn', true),
  (2, 'Молодой крылатый зебрарог', 'Если Молодой крылатый зебрарог покидает игру во время твоей фазы сражения, можешь положить его на верх своей колоды.', 'существо', 1, 2, 5, false, '', '[{"trigger":"conditional","actions":[{"type":"draw_cards","target":"none","filter":"any","count":1,"source":"discard_pile"}],"conditions":[{"type":"if","description":"Молодой крылатый зебрарог покидает игру во время твоей фазы сражения"}],"description":"можешь положить его на верх своей колоды","source_text":"Если Молодой крылатый зебрарог покидает игру во время твоей фазы сражения, можешь положить его на верх своей колоды"}]'::jsonb, 'исходники/карты/jake_2v2_card_24.png', 'corn', true),
  (2, 'Кукурузный гарнизон', 'Твое существо на этой земле получает +1 ATK и +1 DEF за каждого Кукурузного существа под твоим контролем.', 'здание', 2, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/jake_2v2_card_25.png', 'corn', false),
  (2, 'Амбар с сеном', 'Потрать 1 Действие, ПРИЕМ >>> Если эта земля пустует, сыграй на нее Кормежника из стопки сброса бесплатно. Если Амбар с сеном покидает игру, уничтожь Кормежника на этой земле.', 'здание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"manual","target":"none","effect":"Если эта земля пустует, сыграй на нее Кормежника из стопки сброса бесплатно"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Если эта земля пустует, сыграй на нее Кормежника из стопки сброса бесплатно","source_text":"Потрать 1 Действие, ПРИЕМ >>> Если эта земля пустует, сыграй на нее Кормежника из стопки сброса бесплатно"},{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"сыграй на нее Кормежника из стопки сброса бесплатно"}],"conditions":[{"type":"if","description":"эта земля пустует"}],"description":"сыграй на нее Кормежника из стопки сброса бесплатно","source_text":"Если эта земля пустует, сыграй на нее Кормежника из стопки сброса бесплатно"},{"trigger":"conditional","actions":[{"type":"destroy","target":"none","count":1}],"conditions":[{"type":"if","description":"Амбар с сеном покидает игру"}],"description":"уничтожь Кормежника на этой земле","source_text":"Если Амбар с сеном покидает игру, уничтожь Кормежника на этой земле"}]'::jsonb, 'исходники/карты/jake_2v2_card_26.png', 'corn', false),
  (2, 'Слинять', 'Когда выбранное существо атакует в этот ход, оно покидает игру перед фазой сражения, сняв весь урон с него за это.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"on_creature_attacks","actions":[{"type":"passive","target":"none","effect":"в этот ход, оно покидает игру перед фазой сражения, сняв весь урон с него за это"}],"conditions":[],"description":"в этот ход, оно покидает игру перед фазой сражения, сняв весь урон с него за это","source_text":"Когда выбранное существо атакует в этот ход, оно покидает игру перед фазой сражения, сняв весь урон с него за это"}]'::jsonb, 'исходники/карты/jake_2v2_card_28.png', 'corn', false),
  (2, 'Бесконечный комбайн', 'Выбери существо и нанеси себе урон равный остатку DEF, затем уничтожь существо.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"destroy","target":"none","count":1}],"conditions":[{"type":"verb","value":"Выбери"}],"description":"существо и нанеси себе урон равный остатку DEF, затем уничтожь существо","source_text":"Выбери существо и нанеси себе урон равный остатку DEF, затем уничтожь существо"}]'::jsonb, 'исходники/карты/jake_2v2_card_29.png', 'corn', false),
  (2, 'Щенок в заплатках', 'Нанеси 3 урона Щенку в заплатках >>> Он получает +2 ATK в этот ход.', 'существо', 2, 3, 8, false, '', '[]'::jsonb, 'исходники/карты/jake_2v2_card_3.png', 'cute', false),
  (2, 'Кормежник', 'Когда Кормежник вступает в игру, следующее существо введенное в игру в этом ход будет стоить на 1 меньше.', 'существо', 1, 1, 8, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"cost_reduction","amount":1,"target":"self","source_text":"следующее существо введенное в игру в этом ход будет стоить на 1 меньше"}],"conditions":[],"description":"следующее существо введенное в игру в этом ход будет стоить на 1 меньше","source_text":"Когда Кормежник вступает в игру, следующее существо введенное в игру в этом ход будет стоить на 1 меньше"}]'::jsonb, 'исходники/карты/jake_2v2_card_30.png', 'corn', false),
  (2, 'Клон', 'Сыграй свое следующее существо или строение бесплатно, если существо или строение с таким же именем уже в игре.', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Сыграй","target":"none","effect":"свое следующее существо или строение бесплатно, если существо или строение с таким же именем уже в игре"}],"conditions":[{"type":"verb","value":"Сыграй"}],"description":"свое следующее существо или строение бесплатно, если существо или строение с таким же именем уже в игре","source_text":"Сыграй свое следующее существо или строение бесплатно, если существо или строение с таким же именем уже в игре"}]'::jsonb, 'исходники/карты/jake_2v2_card_34.png', 'rainbow', true),
  (2, 'Семейные посиделки', 'Выбери другого игрока и землю под твоим контролем. Каждый тянет карту существа соответствующего этой земле.', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Выбери","target":"none","effect":"другого игрока и землю под твоим контролем"}],"conditions":[{"type":"verb","value":"Выбери"}],"description":"другого игрока и землю под твоим контролем","source_text":"Выбери другого игрока и землю под твоим контролем"}]'::jsonb, 'исходники/карты/jake_2v2_card_35.png', 'rainbow', true),
  (2, 'Королевский тур', 'Если выбранное существо под твоим контролем наносит 1 и более урона противнику в этот ход, то нанеси 2 урона этому же противнику. Как сделал это, передай какрту в руку своему партнеру.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"conditional","actions":[{"type":"deal_damage","target":"none","amount":2,"pierce":false}],"conditions":[{"type":"if","description":"выбранное существо под твоим контролем наносит 1 и более урона противнику в этот ход"}],"description":"нанеси 2 урона этому же противнику","source_text":"Если выбранное существо под твоим контролем наносит 1 и более урона противнику в этот ход, то нанеси 2 урона этому же противнику"}]'::jsonb, 'исходники/карты/jake_2v2_card_36.png', 'rainbow', true),
  (2, 'Овечка', 'Радужное существо', 'существо', 0, 2, 3, false, '', '[]'::jsonb, 'исходники/карты/jake_2v2_card_38.png', 'rainbow', true),
  (2, 'Сшитая белка', 'Если в начале твоего хода у Сшитой белки 4 урона и более, уничтожь выбранное строение противника на этой линии.', 'существо', 1, 2, 8, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"destroy","target":"chosen_opponent_creature","count":1}],"conditions":[],"description":"в начале твоего хода у Сшитой белки 4 урона и более, уничтожь выбранное строение противника на этой линии","source_text":"в начале твоего хода у Сшитой белки 4 урона и более, уничтожь выбранное строение противника на этой линии"},{"trigger":"conditional","actions":[{"type":"destroy","target":"chosen_opponent_creature","count":1}],"conditions":[{"type":"if","description":"в начале твоего хода у Сшитой белки 4 урона и более"}],"description":"уничтожь выбранное строение противника на этой линии","source_text":"Если в начале твоего хода у Сшитой белки 4 урона и более, уничтожь выбранное строение противника на этой линии"}]'::jsonb, 'исходники/карты/jake_2v2_card_4.png', 'cute', false),
  (2, 'Содействие', 'В начале фазы фракинга твой твёрдо друга, если ты партнёр, если ты партнёр не сыграл существо в этом ходе, другой партнёр может бесплатно сыграть существо стоимостью 1 или менее.', 'special', 1, NULL, NULL, false, '', '[{"trigger":"conditional","actions":[{"type":"play_for_free","target":"creature","cost_filter":null,"source_text":"другой партнёр может бесплатно сыграть существо стоимостью 1 или менее"}],"conditions":[{"type":"if","description":"ты партнёр"}],"description":"если ты партнёр не сыграл существо в этом ходе, другой партнёр может бесплатно сыграть существо стоимостью 1 или менее","source_text":"если ты партнёр, если ты партнёр не сыграл существо в этом ходе, другой партнёр может бесплатно сыграть существо стоимостью 1 или менее"}]'::jsonb, 'исходники/карты/jake_2v2_card_40.png', 'corn', false),
  (2, 'Куча мала', 'Дружественные существа получают +1 ATK до начала следующей фазы сражения. Затем каждое существо наносит урон равный его ATK существу противника на этой линии.', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/jake_2v2_card_5.png', 'cute', true),
  (2, 'Заплатка', 'Перераспредели урон на существах под твоим контролем (сделай это так, чтобы урона было не больше DEF).', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/jake_2v2_card_6.png', 'cute', false),
  (2, 'Сплочённость', 'Первое существо, которое атакует другое существо в течении хода твоей команды, получает +1 АТК в этот ход.', 'special', 2, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/jake_2v2_card_7.png', 'cute', false),
  (2, 'Крепость из подушек', 'Потрать 1 Действие, ПРИЕМ >>> Восстанови или нанеси 2 урона выбранному существу под твоим контролем на этой земле. Проделай то же самое с другим дружественным существом.', 'здание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"deal_damage","target":"chosen_creature","amount":2,"pierce":false}],"conditions":[{"type":"cost_actions","value":1}],"description":"Восстанови или нанеси 2 урона выбранному существу под твоим контролем на этой земле","source_text":"Потрать 1 Действие, ПРИЕМ >>> Восстанови или нанеси 2 урона выбранному существу под твоим контролем на этой земле"}]'::jsonb, 'исходники/карты/jake_2v2_card_8.png', 'cute', false),
  (1, 'Фермер-кочевник', 'Когда Фермер-кочевник покидает игру, нанеси 1 урон противнику за каждую карту в его руке.', 'существо', 2, 2, 12, false, '', '[]'::jsonb, 'исходники/карты/jake_card_1.png', 'corn', false),
  (11, 'Червь шелухи', 'Когда Червь шелухи вступает в игру, переверни Кукурузное поле под твоим контролем лицом вниз.', 'существо', 1, 5, 4, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"flip_landscape","target":"this_landscape","face":"down"}],"conditions":[],"description":"переверни Кукурузное поле под твоим контролем лицом вниз","source_text":"Когда Червь шелухи вступает в игру, переверни Кукурузное поле под твоим контролем лицом вниз"}]'::jsonb, 'исходники/карты/jake_card_11.png', 'corn', false),
  (13, 'Легион уховерток', 'Когда Легион уховерток вступает в игру, можешь вернуть выбранное существо на этой линии его владельцу.', 'существо', 2, 2, 8, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"passive","target":"none","effect":"можешь вернуть выбранное существо на этой линии его владельцу"}],"conditions":[],"description":"можешь вернуть выбранное существо на этой линии его владельцу","source_text":"Когда Легион уховерток вступает в игру, можешь вернуть выбранное существо на этой линии его владельцу"}]'::jsonb, 'исходники/карты/jake_card_13.png', 'corn', false),
  (14, 'Легион уховёрток', 'Когда Легион уховёрток вступает в игру, можешь вернуть выбранное существо на этой линии его владельцу.', 'существо', 2, 2, 8, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"passive","target":"none","effect":"можешь вернуть выбранное существо на этой линии его владельцу"}],"conditions":[],"description":"можешь вернуть выбранное существо на этой линии его владельцу","source_text":"Когда Легион уховёрток вступает в игру, можешь вернуть выбранное существо на этой линии его владельцу"}]'::jsonb, 'исходники/карты/jake_card_14.png', 'corn', false),
  (15, 'Разбойная тыква', 'ПРИЕМ >>> Наносит 1 урон выбранному существу. Повтори это за каждое Кукурузное поле под твоим контролем. (Может повредить каждое существо только 1 раз.)', 'существо', 1, 0, 5, false, '', '[{"trigger":"manual","actions":[{"type":"deal_damage","target":"chosen_creature","amount":1,"pierce":false}],"conditions":[{"type":"cost_actions","value":1}],"description":"Наносит 1 урон выбранному существу","source_text":"ПРИЕМ >>> Наносит 1 урон выбранному существу"}]'::jsonb, 'исходники/карты/jake_card_15.png', 'corn', false),
  (18, 'Царь полей', 'Царь полей получает +1 ATK за каждое другое Кукурузное существо под твоим контролем.', 'существо', 1, 0, 7, false, '', '[]'::jsonb, 'исходники/карты/jake_card_18.png', 'corn', false),
  (19, 'Кукурузный ронин', '+1 ATK за каждое соседнее Кукурузное поле.', 'существо', 1, 1, 6, false, '', '[]'::jsonb, 'исходники/карты/jake_card_19.png', 'corn', false),
  (21, 'Зернотавр', 'Когда Зернотавр вступает в игру, он наносит 1 урон противнику за каждое Кукурузное поле под твоим контролем.', 'существо', 2, 2, 10, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"deal_damage","target":"each_creature_opponent","amount":1,"pierce":false}],"conditions":[],"description":"он наносит 1 урон противнику за каждое Кукурузное поле под твоим контролем","source_text":"Когда Зернотавр вступает в игру, он наносит 1 урон противнику за каждое Кукурузное поле под твоим контролем"}]'::jsonb, 'исходники/карты/jake_card_21.png', 'corn', false),
  (23, 'Призрак полей', 'В начале твоего хода каждый игрок тянет карту.', 'существо', 1, 1, 10, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"draw_cards","target":"none","count":1,"source":"deck"}],"conditions":[],"description":"В начале твоего хода каждый игрок тянет карту","source_text":"В начале твоего хода каждый игрок тянет карту"}]'::jsonb, 'исходники/карты/jake_card_23.png', 'corn', false),
  (25, 'Башня правды', 'Потрать 2 действия >>> Укради случайную карту с руки противника и сыграй ее бесплатно.', 'здание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/jake_card_25.png', 'corn', false),
  (28, 'Перекрестное опыление', 'Каждое твое Кукурузное существо получает +1 ATK в этом ходу за каждый уникальный тип земель под твоим контролем.', 'заклинание', 2, NULL, NULL, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"stat_buff","target":"this_creature","stat":"attack","amount":1,"duration":"this_turn"}],"conditions":[],"description":"получает +1 ATK в этом ходу","source_text":"получает +1 ATK в этом ходу"}]'::jsonb, 'исходники/карты/jake_card_28.png', 'rainbow', true),
  (29, 'Восстановление ландшафта', 'Можешь перевернуть одну свою землю лицом вверх. Можешь переместить одно свое строение на свою линию без строений.', 'заклинание', 0, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/jake_card_29.png', 'rainbow', true),
  (3, 'Стена початков', '+1 DEF за каждое Кукурузное поле в игре (у всех игроков).', 'существо', 1, 2, 4, false, '', '[]'::jsonb, 'исходники/карты/jake_card_3.png', 'corn', false),
  (31, 'Кукурузный скипетр', 'Наносит 1 урон выбранному существу за каждое Кукурузное поле под твоим контролем.', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/jake_card_31.png', 'rainbow', true),
  (36, 'Злое око', 'Зло таится в глазах смотрящего.', 'существо', 0, 1, 5, false, '', '[]'::jsonb, 'исходники/карты/jake_card_36.png', 'rainbow', true),
  (37, 'Филлис', 'Она отвлекает тебя клинком, чтобы отдубасить тебя сумкой.', 'существо', 1, 2, 7, false, '', '[]'::jsonb, 'исходники/карты/jake_card_37.png', 'rainbow', true),
  (38, 'Слюнявый чел', 'Девушки в калошах любят его.', 'существо', 2, 3, 9, false, '', '[]'::jsonb, 'исходники/карты/jake_card_38.png', 'rainbow', true),
  (39, 'БигФут', 'ПРИЕМ >>> Переверни выбранную землю под твоим контролем лицом вверх.', 'существо', 0, 1, 4, false, '', '[{"trigger":"manual","actions":[{"type":"flip_landscape","target":"chosen_landscape","face":"down"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Переверни выбранную землю под твоим контролем лицом вве","source_text":"ПРИЕМ >>> Переверни выбранную землю под твоим контролем лицом вве"}]'::jsonb, 'исходники/карты/jake_card_39.png', 'rainbow', true),
  (5, 'Кукурузный пес', 'Кукурузный пес получает +1 DEF за каждое Кукурузное поле под твоим контролем. Если их 3 или меньше, то также +1 ATK.', 'существо', 1, 0, 12, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"также +1 ATK"}],"conditions":[{"type":"if","description":"их 3 или меньше"}],"description":"также +1 ATK","source_text":"Если их 3 или меньше, то также +1 ATK"}]'::jsonb, 'исходники/карты/jake_card_5.png', 'corn', false),
  (6, 'Жнец', 'Дополнительная плата: сбрось карту. Когда Жнец вступает в игру, перемести существо на этой линии на пустую соседнюю линию (на своей стороне).', 'существо', 2, 1, 4, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[],"description":"перемести существо на этой линии на пустую соседнюю линию (на своей стороне)","source_text":"Когда Жнец вступает в игру, перемести существо на этой линии на пустую соседнюю линию (на своей стороне)"}]'::jsonb, 'исходники/карты/jake_card_6.png', 'corn', false),
  (7, 'Поля кошмаров', 'Наносям 1 урон противнику за каждую карту в его руке.', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/jake_card_7.png', 'corn', false),
  (1, 'Песчаный сфинкс', 'ПРИЕМ >>> Верни существо под твоим контролем на этой линии в руку владельцу.', 'существо', 2, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"manual","target":"none","effect":"Верни существо под твоим контролем на этой линии в руку владель"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Верни существо под твоим контролем на этой линии в руку владель","source_text":"ПРИЕМ >>> Верни существо под твоим контролем на этой линии в руку владель"}]'::jsonb, 'исходники/карты/lady_rainicorn_card_1.png', 'sand', false),
  (10, 'Акула', 'Когда песчаное существо вступает в игру во время твоего хода (включая Акулу), оно получает +1 АТК в этом ходу.', 'существо', 2, 2, 10, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"passive","target":"none","effect":"во время твоего хода (включая Акулу), оно получает +1 АТК в этом ходу"}],"conditions":[],"description":"во время твоего хода (включая Акулу), оно получает +1 АТК в этом ходу","source_text":"Когда песчаное существо вступает в игру во время твоего хода (включая Акулу), оно получает +1 АТК в этом ходу"},{"trigger":"on_enters_play","actions":[{"type":"stat_buff","target":"this_creature","stat":"attack","amount":1,"duration":"this_turn"}],"conditions":[],"description":"получает +1 АТК в этом ходу","source_text":"получает +1 АТК в этом ходу"}]'::jsonb, 'исходники/карты/lady_rainicorn_card_10.png', 'sand', false),
  (12, 'Мариачи', 'ПРИЕМ >>> Нанеси 1 урон выбранному существу за каждое существо вступившее в игру в этот ход.', 'существо', 2, 2, 9, false, '', '[{"trigger":"manual","actions":[{"type":"deal_damage","target":"each_creature","amount":1,"pierce":false}],"conditions":[{"type":"cost_actions","value":1}],"description":"Нанеси 1 урон выбранному существу за каждое существо вступившее в игру в этот х","source_text":"ПРИЕМ >>> Нанеси 1 урон выбранному существу за каждое существо вступившее в игру в этот х"}]'::jsonb, 'исходники/карты/lady_rainicorn_card_12.png', 'sand', false),
  (14, 'Песчаный змей', 'Когда Песчаный змей вступает в игру, нанеси 4 урона выбранному существу противника на этой линии.', 'существо', 1, 0, 9, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"deal_damage","target":"chosen_opponent_creature","amount":4,"pierce":false}],"conditions":[],"description":"нанеси 4 урона выбранному существу противника на этой линии","source_text":"Когда Песчаный змей вступает в игру, нанеси 4 урона выбранному существу противника на этой линии"}]'::jsonb, 'исходники/карты/lady_rainicorn_card_14.png', 'sand', false),
  (16, 'Муми-тролль', 'ПРИЕМ >>> Получи 1 Действие в этом ход.', 'существо', 1, 2, 7, false, '', '[{"trigger":"manual","actions":[{"type":"gain_actions","target":"none","count":1}],"conditions":[{"type":"cost_actions","value":1}],"description":"Получи 1 Действие в этом х","source_text":"ПРИЕМ >>> Получи 1 Действие в этом х"}]'::jsonb, 'исходники/карты/lady_rainicorn_card_16.png', 'sand', false),
  (17, 'Домашний кактус', '+2 ATK за каждый Домашний кактус под твоим контролем.', 'существо', 1, 0, 4, false, '', '[]'::jsonb, 'исходники/карты/lady_rainicorn_card_17.png', 'sand', false),
  (19, 'Затерянный голем', 'Затерянный голем стоит на 1 меньше за каждое другое существо сыгранное в этом ходу.', 'существо', 3, 5, 6, false, '', '[]'::jsonb, 'исходники/карты/lady_rainicorn_card_19.png', 'sand', false),
  (20, 'Песчаная мышь', 'Песчаная мышь получает 1 DEF за каждое другое существо вступившее в игру под твоим контролем.', 'существо', 2, 1, 10, false, '', '[]'::jsonb, 'исходники/карты/lady_rainicorn_card_20.png', 'sand', false),
  (22, 'Песчаные рыцари', '+2 ATK если под твоим контролем Голубые равнины.', 'существо', 1, 1, 8, false, '', '[]'::jsonb, 'исходники/карты/lady_rainicorn_card_22.png', 'sand', false),
  (23, 'Песчаный глазастик', 'Когда Песчаный глазастик вступает в игру, нанеси 1 урон каждому существу в игре, (включая каждое твое существо).', 'существо', 1, 3, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"deal_damage","target":"each_creature","amount":1,"pierce":false}],"conditions":[],"description":"нанеси 1 урон каждому существу в игре, (включая каждое твое существо)","source_text":"Когда Песчаный глазастик вступает в игру, нанеси 1 урон каждому существу в игре, (включая каждое твое существо)"}]'::jsonb, 'исходники/карты/lady_rainicorn_card_23.png', 'sand', false),
  (25, 'Волшебные семена Зазо', 'Выбранное песчаное существо получает +2 АТК в этом ход за каждое существо, вступившее в игру на соседнюю линию в этом ход.', 'здание', 0, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lady_rainicorn_card_25.png', 'rainbow', true),
  (3, 'Фолианкх', 'Тяни карту за каждую свою пустую линию.', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lady_rainicorn_card_3.png', 'sand', false),
  (34, 'Песчаный ангел', 'Ложись на песок, подвигай руками и ногами, и она придёт к тебе.', 'существо', 0, 1, 5, false, '', '[]'::jsonb, 'исходники/карты/lady_rainicorn_card_34.png', 'rainbow', false),
  (36, 'Персиковая Джинни', 'Когда песчаное существо вступает в игру под твоим контролем, Персиковая Джинни получает +1 ATK в этом ходу.', 'существо', 0, 0, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"passive","target":"none","effect":"под твоим контролем, Персиковая Джинни получает +1 ATK в этом ходу"}],"conditions":[],"description":"под твоим контролем, Персиковая Джинни получает +1 ATK в этом ходу","source_text":"Когда песчаное существо вступает в игру под твоим контролем, Персиковая Джинни получает +1 ATK в этом ходу"},{"trigger":"on_enters_play","actions":[{"type":"stat_buff","target":"this_creature","stat":"attack","amount":1,"duration":"this_turn"}],"conditions":[],"description":"получает +1 ATK в этом ходу","source_text":"получает +1 ATK в этом ходу"}]'::jsonb, 'исходники/карты/lady_rainicorn_card_36.png', 'rainbow', true),
  (39, 'Непустой гроб', 'Следующее существо сыгранное тобой в этот ход стоит на 2 действия меньше.', 'заклинание', 0, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lady_rainicorn_card_39.png', 'rainbow', false),
  (6, 'Стена песка', 'Если другое песчаное существо, одно или более, вступает в игру во время твоего хода, Песчаная стена получает +2 ATK в этот ход.', 'существо', 2, 1, 12, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"одно или более, вступает в игру во время твоего хода, Песчаная стена получает +2 ATK в этот ход"}],"conditions":[{"type":"if","description":"другое песчаное существо"}],"description":"одно или более, вступает в игру во время твоего хода, Песчаная стена получает +2 ATK в этот ход","source_text":"Если другое песчаное существо, одно или более, вступает в игру во время твоего хода, Песчаная стена получает +2 ATK в этот ход"}]'::jsonb, 'исходники/карты/lady_rainicorn_card_6.png', 'sand', false),
  (8, 'Сэндвич', 'Когда Сэндвич или другое песчаное существо вступает в игру под твоим контролем, нанеси 1 урон своему противнику.', 'существо', 1, 0, 12, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"deal_damage","target":"none","amount":1,"pierce":false}],"conditions":[],"description":"под твоим контролем, нанеси 1 урон своему противнику","source_text":"Когда Сэндвич или другое песчаное существо вступает в игру под твоим контролем, нанеси 1 урон своему противнику"}]'::jsonb, 'исходники/карты/lady_rainicorn_card_8.png', 'sand', false),
  (1, 'Драконий поп-десант', 'Когда Драконий поп-десант вступает в игру, перемести его на пустую землю. Его нельзя заменить. Соседние существа получают -1 АТК.', 'существо', 2, 1, 8, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[],"description":"перемести его на пустую землю","source_text":"Когда Драконий поп-десант вступает в игру, перемести его на пустую землю"}]'::jsonb, 'исходники/карты/lemongrab_card_1.png', 'rainbow', true),
  (10, 'Зона высадки', 'Выбери свое существо и верни его на руку.', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Выбери","target":"none","effect":"свое существо и верни его на руку"}],"conditions":[{"type":"verb","value":"Выбери"}],"description":"свое существо и верни его на руку","source_text":"Выбери свое существо и верни его на руку"}]'::jsonb, 'исходники/карты/lemongrab_card_10.png', 'rainbow', true),
  (11, 'Мясной кулак', 'Выбранное существо под твоим контролем получает -5 АТК в этот ход.
Тяни карту.', 'заклинание', 0, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lemongrab_card_11.png', 'rainbow', true),
  (12, 'Ты жжошь!', 'Переверни выбранную землю лицом вниз до начала твоего следующего хода.', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"flip_landscape","target":"chosen_landscape","face":"down"}],"conditions":[{"type":"verb","value":"Переверни"}],"description":"выбранную землю лицом вниз до начала твоего следующего хода","source_text":"Переверни выбранную землю лицом вниз до начала твоего следующего хода"}]'::jsonb, 'исходники/карты/lemongrab_card_12.png', 'rainbow', true),
  (14, 'Аванпост попугаев', 'Каждое существо на этой линии получает -1 АТК (минимум 0).', 'здание', 0, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lemongrab_card_14.png', 'rainbow', true),
  (15, 'Теплый прием', 'Верни выбранное существо владельцу в руку. Получи количество действий равных ее стоимости.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Верни","target":"none","effect":"выбранное существо владельцу в руку"}],"conditions":[{"type":"verb","value":"Верни"}],"description":"выбранное существо владельцу в руку","source_text":"Верни выбранное существо владельцу в руку"}]'::jsonb, 'исходники/карты/lemongrab_card_15.png', 'sand', false),
  (16, 'Закусочная', 'ПРИЕМ >>> Тяни карту за каждое существо введённое в игру на эту землю в этом ходу.', 'здание', 2, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"draw_cards","target":"none","count":1,"source":"deck"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Тяни карту за каждое существо введённое в игру на эту землю в этом хо","source_text":"ПРИЕМ >>> Тяни карту за каждое существо введённое в игру на эту землю в этом хо"}]'::jsonb, 'исходники/карты/lemongrab_card_16.png', 'sand', false),
  (17, 'Помпезный зебрагог', '+1 DEF за каждый различный тип земли под твоим контролем.', 'существо', 1, 2, 4, false, '', '[]'::jsonb, 'исходники/карты/lemongrab_card_17.png', 'corn', false),
  (18, 'Помпезный зобрагор', '+1 DEF за каждый различный тип земли под твоим контролем.', 'существо', 1, 2, 4, false, '', '[]'::jsonb, 'исходники/карты/lemongrab_card_18.png', 'corn', false),
  (19, 'Крушитель земли', 'Когда Крушитель земли вступает в игру, переверни землю на этой линии лицом вниз. Когда он покидает игру, переверни ее лицом вверх.', 'существо', 1, 1, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"flip_landscape","target":"this_landscape","face":"down"}],"conditions":[],"description":"переверни землю на этой линии лицом вниз","source_text":"Когда Крушитель земли вступает в игру, переверни землю на этой линии лицом вниз"}]'::jsonb, 'исходники/карты/lemongrab_card_19.png', 'corn', false),
  (2, 'Мясной поп-десапт', 'Когда Мясной поп-десапт вступает в игру, перемести его на пустую землю, затем переверни эту землю лицом вниз.', 'существо', 2, 2, 4, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"},{"type":"flip_landscape","target":"this_landscape","face":"down"}],"conditions":[],"description":"перемести его на пустую землю, затем переверни эту землю лицом вниз","source_text":"Когда Мясной поп-десапт вступает в игру, перемести его на пустую землю, затем переверни эту землю лицом вниз"}]'::jsonb, 'исходники/карты/lemongrab_card_2.png', 'rainbow', true),
  (21, 'Дрожь земли', '+2 ATK за каждую землю в игре, перевёрнутую лицом вниз.', 'существо', 1, 1, 7, false, '', '[]'::jsonb, 'исходники/карты/lemongrab_card_21.png', 'corn', false),
  (24, 'Зебрарог на подборе', '+1 АТК за каждый различный тип земли под твоим контролем.', 'существо', 1, 0, 6, false, '', '[]'::jsonb, 'исходники/карты/lemongrab_card_24.png', 'corn', false),
  (26, 'Рок-н-рольщик', 'Когда Рок-н-рольщик вступает в игру, переверни землю на этой линии лицом вниз. Когда он покидает игру, переверни ее лицом вверх.', 'существо', 2, 2, 8, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"flip_landscape","target":"this_landscape","face":"down"}],"conditions":[],"description":"переверни землю на этой линии лицом вниз","source_text":"Когда Рок-н-рольщик вступает в игру, переверни землю на этой линии лицом вниз"}]'::jsonb, 'исходники/карты/lemongrab_card_26.png', 'corn', false),
  (27, 'Рок-н-ролльщик', 'Когда Рок-н-ролльщик вступает в игру, переверни землю на этой линии лицом вниз. Когда он покидает игру, переверни ее лицом вверх.', 'существо', 2, 2, 8, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"flip_landscape","target":"this_landscape","face":"down"}],"conditions":[],"description":"переверни землю на этой линии лицом вниз","source_text":"Когда Рок-н-ролльщик вступает в игру, переверни землю на этой линии лицом вниз"}]'::jsonb, 'исходники/карты/lemongrab_card_27.png', 'corn', false),
  (28, 'Лавина Маиса', 'Каждое твоё существо получает +1 ATK в этом ходу за каждую землю в игре, перевёрнутую лицом вниз.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"persistent","actions":[{"type":"stat_buff","target":"each_creature","stat":"attack","amount":1,"duration":"this_turn"}],"conditions":[],"description":"Каждое твоё существо получает +1 ATK","source_text":"Каждое твоё существо получает +1 ATK"},{"trigger":"on_enters_play","actions":[{"type":"stat_buff","target":"this_creature","stat":"attack","amount":1,"duration":"this_turn"}],"conditions":[],"description":"получает +1 ATK в этом ходу","source_text":"получает +1 ATK в этом ходу"}]'::jsonb, 'исходники/карты/lemongrab_card_28.png', 'corn', false),
  (29, 'Башня свободы', 'Сбрось карту >>> Твоя земля на этой линии теряет свой тип земли и берет тип по твоему выбору (кроме перевернутых) до начала твоего следующего хода.', 'здание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"verb","value":"Сбрось"}],"description":"карту >>> Твоя земля на этой линии теряет свой тип земли и берет тип по твоему выбору (кроме перевернутых) до начала твоего следующего хода","source_text":"Сбрось карту >>> Твоя земля на этой линии теряет свой тип земли и берет тип по твоему выбору (кроме перевернутых) до начала твоего следующего хода"}]'::jsonb, 'исходники/карты/lemongrab_card_29.png', 'corn', false),
  (3, 'Невезучий поп-десант', 'Когда Невезучий поп-десант вступает в игру, перемести его на пустую землю. Его нельзя заменить. В начале своего хода сбрось карту.', 'существо', 1, 1, 5, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[],"description":"перемести его на пустую землю","source_text":"Когда Невезучий поп-десант вступает в игру, перемести его на пустую землю"},{"trigger":"start_of_turn","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[],"description":"В начале своего хода сбрось карту","source_text":"В начале своего хода сбрось карту"}]'::jsonb, 'исходники/карты/lemongrab_card_3.png', 'rainbow', true),
  (30, 'Воронка', 'Сбрось карту, ПРИЕМ >>> Переверни выбранную землю на этой линии лицом вниз до начала твоего следующего хода.', 'здание', 2, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"flip_landscape","target":"chosen_landscape","face":"down"}],"conditions":[{"type":"prerequisite","description":"Сбрось карту"}],"description":"Переверни выбранную землю на этой линии лицом вниз до начала твоего следующего хо","source_text":"Сбрось карту, ПРИЕМ >>> Переверни выбранную землю на этой линии лицом вниз до начала твоего следующего хо"},{"trigger":"manual","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false},{"type":"flip_landscape","target":"chosen_landscape","face":"down"}],"conditions":[{"type":"verb","value":"Сбрось"}],"description":"карту, ПРИЕМ >>> Переверни выбранную землю на этой линии лицом вниз до начала твоего следующего хода","source_text":"Сбрось карту, ПРИЕМ >>> Переверни выбранную землю на этой линии лицом вниз до начала твоего следующего хода"}]'::jsonb, 'исходники/карты/lemongrab_card_30.png', 'corn', false),
  (31, 'Скачущий зебрарог', '+1 ATK за каждый различный тип земли под твоим контролем.', 'существо', 2, 1, 9, false, '', '[]'::jsonb, 'исходники/карты/lemongrab_card_31.png', 'corn', true),
  (32, 'Смещатель земли', '+2 ATK за каждую землю в царстве перевернутую лицом вниз.', 'существо', 2, 2, 10, false, '', '[]'::jsonb, 'исходники/карты/lemongrab_card_32.png', 'corn', false),
  (33, 'Каракум', 'Когда существо под твоим контролем покидает игру, можешь подложить его под эту карту. +1 ATK и +1 DEF за каждую карту под ней. Когда она покидает игру сбрось все карты под ней.', 'существо', 1, 0, 4, false, '', '[]'::jsonb, 'исходники/карты/lemongrab_card_33.png', 'sand', false),
  (34, 'Муми Ба', 'В начале своего хода можешь вернуть Муми Ба в руку его владельца. Если сделаешь это, тяни две карты.', 'существо', 1, 3, 3, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"return_from_discard","target":"this_creature","destination":"hand"}],"conditions":[],"description":"В начале своего хода можешь вернуть Муми Ба в руку его владельца","source_text":"В начале своего хода можешь вернуть Муми Ба в руку его владельца"},{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"тяни две карты"}],"conditions":[{"type":"if","description":"сделаешь это"}],"description":"тяни две карты","source_text":"Если сделаешь это, тяни две карты"}]'::jsonb, 'исходники/карты/lemongrab_card_34.png', 'sand', false),
  (36, 'Пескомаг', 'В начале своего хода можешь вернуть Пескомага в руку его владельца. Если сделаешь это, каждое существо под твоим контролем получает +1 в этом ход.', 'существо', 1, 2, 4, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"return_from_discard","target":"this_creature","destination":"hand"}],"conditions":[],"description":"В начале своего хода можешь вернуть Пескомага в руку его владельца","source_text":"В начале своего хода можешь вернуть Пескомага в руку его владельца"},{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"каждое существо под твоим контролем получает +1 в этом ход"}],"conditions":[{"type":"if","description":"сделаешь это"}],"description":"каждое существо под твоим контролем получает +1 в этом ход","source_text":"Если сделаешь это, каждое существо под твоим контролем получает +1 в этом ход"}]'::jsonb, 'исходники/карты/lemongrab_card_36.png', 'sand', false),
  (38, 'Ска-пион', 'Пока противник контролирует твое существо, Ска-пион стоит на 1 меньше, чтобы сыграть его.', 'существо', 1, 3, 3, false, '', '[{"trigger":"persistent","actions":[{"type":"cost_reduction","amount":1,"target":"self","source_text":"Ска-пион стоит на 1 меньше"}],"conditions":[{"type":"while","description":"противник контролирует твое существо"}],"description":"Ска-пион стоит на 1 меньше, чтобы сыграть его","source_text":"Пока противник контролирует твое существо, Ска-пион стоит на 1 меньше, чтобы сыграть его"}]'::jsonb, 'исходники/карты/lemongrab_card_38.png', 'sand', false),
  (39, 'Свободное падение', 'Каждое твоё существо получает +1 ATK в этом ходу за каждое существо введённое в игру в этот ход.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"persistent","actions":[{"type":"stat_buff","target":"each_creature","stat":"attack","amount":1,"duration":"this_turn"}],"conditions":[],"description":"Каждое твоё существо получает +1 ATK","source_text":"Каждое твоё существо получает +1 ATK"},{"trigger":"on_enters_play","actions":[{"type":"stat_buff","target":"this_creature","stat":"attack","amount":1,"duration":"this_turn"}],"conditions":[],"description":"получает +1 ATK в этом ходу","source_text":"получает +1 ATK в этом ходу"}]'::jsonb, 'исходники/карты/lemongrab_card_39.png', 'sand', false),
  (5, 'Статичный поп-десапт', 'Когда Статичный поп-десапт вступает в игру, перемести его на пустую землю. Его нельзя заменить. В начале своего следующего хода нанеси 1 урон своему герою.', 'существо', 0, 0, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[],"description":"перемести его на пустую землю","source_text":"Когда Статичный поп-десапт вступает в игру, перемести его на пустую землю"}]'::jsonb, 'исходники/карты/lemongrab_card_5.png', 'rainbow', true),
  (6, 'Статичный поп-десант', 'Когда Статичный поп-десант вступает в игру, перемести его на пустую землю. Его нельзя заменить. В начале своего следующего хода нанеси 1 урон своему герою.', 'существо', 0, 0, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[],"description":"перемести его на пустую землю","source_text":"Когда Статичный поп-десант вступает в игру, перемести его на пустую землю"}]'::jsonb, 'исходники/карты/lemongrab_card_6.png', 'rainbow', true),
  (7, 'Бабах', 'Когда Бабах покидает игру нанеси 1 урон каждому соседнему существу.', 'существо', 0, 0, 5, false, '', '[]'::jsonb, 'исходники/карты/lemongrab_card_7.png', 'rainbow', true),
  (10, 'Дух Воплекурга', 'Приём: Оглушительный "Кудах!". Наносит 1 урон всем существам противника ИЛИ 3 урона существу перед Духом Воплекурга.', 'существо', 2, 1, 9, false, '', '[]'::jsonb, 'исходники/карты/lich_card_10.png', 'undead', false),
  (11, 'Призрак карги', 'Не успокоится даже после смерти. +1 АТК против милых и кукурузных существ. Если Карга убивает существо, твой противник получает урон, равный его стоимости.', 'существо', 2, 2, 9, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"твой противник получает урон, равный его стоимости"}],"conditions":[{"type":"if","description":"Карга убивает существо"}],"description":"твой противник получает урон, равный его стоимости","source_text":"Если Карга убивает существо, твой противник получает урон, равный его стоимости"}]'::jsonb, 'исходники/карты/lich_card_11.png', 'undead', false),
  (13, 'Бестелесый обжор', 'Обжор поглощает другие души (и всё остальное). Если призрачное существо под твоим контролем умирает, положи его карту под обжора - он получит +1 ATK и +2 DEF навсегда.', 'существо', 1, 3, 5, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"положи его карту под обжора - он получит +1 ATK и +2 DEF навсегда"}],"conditions":[{"type":"if","description":"призрачное существо под твоим контролем умирает"}],"description":"положи его карту под обжора - он получит +1 ATK и +2 DEF навсегда","source_text":"Если призрачное существо под твоим контролем умирает, положи его карту под обжора - он получит +1 ATK и +2 DEF навсегда"}]'::jsonb, 'исходники/карты/lich_card_13.png', 'undead', false),
  (15, 'Призрак Тэдди-крюка', 'На Абордаж! Тэдди-крюк при атаке вражеского существа получает бонус +1 ATK за каждое из соседних с целью вражеских существ.', 'существо', 2, 2, 8, false, '', '[]'::jsonb, 'исходники/карты/lich_card_15.png', 'undead', false),
  (16, 'Некромама', 'Прицеп >>> Перемешай сброс рубашкой вверх и тяни карты, пока не попадётся Коричневый зомби или Приятный скелет, после сыграй их. Если места нет, прицеп не работает.', 'существо', 2, 0, 7, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"прицеп не работает"}],"conditions":[{"type":"if","description":"места нет"}],"description":"прицеп не работает","source_text":"Если места нет, прицеп не работает"},{"trigger":"persistent","actions":[{"type":"passive","target":"none","effect":"после сыграй их"}],"conditions":[{"type":"while","description":"не попадётся Коричневый зомби или Приятный скелет"}],"description":"после сыграй их","source_text":"пока не попадётся Коричневый зомби или Приятный скелет, после сыграй их"}]'::jsonb, 'исходники/карты/lich_card_16.png', 'undead', false),
  (17, 'Приятный скелет', '"Добрый вечер!" +1 DEF, если на поле есть ещё один Приятный скелет.', 'существо', 1, 2, 4, false, '', '[]'::jsonb, 'исходники/карты/lich_card_17.png', 'undead', false),
  (19, 'Коричный зомби', '"Не такой уж и сладкий"', 'существо', 1, 1, 6, false, '', '[]'::jsonb, 'исходники/карты/lich_card_19.png', 'undead', false),
  (21, 'Духо-муха', 'Перед смертью больно бросает косу в существо противника, нанося дополнительно 1 урон (касается только убившего муху существа).', 'существо', 1, 3, 3, false, '', '[]'::jsonb, 'исходники/карты/lich_card_21.png', 'undead', false),
  (24, 'Призрачные бро', 'Настолько крутые ребята, что существа противника просто не могут дать им сдачи (не получают урон при нападении на существо противника).', 'существо', 1, 1, 7, false, '', '[]'::jsonb, 'исходники/карты/lich_card_24.png', 'undead', false),
  (26, 'Зомбанан', 'Если у противника под контролем находятся 2 существа или меньше, получаем +1 АТК.', 'существо', 1, 1, 6, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"получаем +1 АТК"}],"conditions":[{"type":"if","description":"у противника под контролем находятся 2 существа или меньше"}],"description":"получаем +1 АТК","source_text":"Если у противника под контролем находятся 2 существа или меньше, получаем +1 АТК"}]'::jsonb, 'исходники/карты/lich_card_26.png', 'undead', false),
  (28, 'Угнетающая пирамида', 'Существо противника на этой линии получает -2 DEF. Показатель DEF существа при этом не может стать меньше 1.', 'здание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lich_card_28.png', 'undead', false),
  (29, 'Преобразователь скелетов', 'За каждое погибшее на этой линии существо (твоё или противника) восстанавливает 1 урон всем твоим существам.', 'здание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lich_card_29.png', 'undead', false),
  (3, 'Прозрачный вышибала', 'Прозрачный вышибала получает бонус +1 ATK за каждое другое призрачное существо на соседних землях.', 'существо', 2, 2, 9, false, '', '[]'::jsonb, 'исходники/карты/lich_card_3.png', 'undead', false),
  (30, 'Призрачный шмяк', 'Уничтожь выбранное строение противника.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"destroy","target":"chosen_opponent","count":1}],"conditions":[{"type":"verb","value":"Уничтожь"}],"description":"выбранное строение противника","source_text":"Уничтожь выбранное строение противника"}]'::jsonb, 'исходники/карты/lich_card_30.png', 'undead', false),
  (32, 'Корова-нежить', '"Му?"', 'существо', 0, 1, 4, false, '', '[]'::jsonb, 'исходники/карты/lich_card_32.png', 'rainbow', true),
  (34, 'Му-бык', 'Получает +1 ATK, когда атакует существ с жёлтым цветом на них (он просто его не любит).', 'существо', 1, 1, 6, false, '', '[]'::jsonb, 'исходники/карты/lich_card_34.png', 'rainbow', true),
  (36, 'Вместе навсегда', 'Распредели урон между двумя существами под твоим контролем, как тебе нужно. Урон на одном существе не может равняться его DEF.', 'заклинание', 0, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lich_card_36.png', 'rainbow', true),
  (37, 'Последний шанс', 'Уничтожь своё существо без урона на нём, затем возьми и бесплатно сыграй любое существо из твоего сброса или сброса противника.', 'заклинание', 2, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"destroy","target":"none","count":1}],"conditions":[{"type":"verb","value":"Уничтожь"}],"description":"своё существо без урона на нём, затем возьми и бесплатно сыграй любое существо из твоего сброса или сброса противника","source_text":"Уничтожь своё существо без урона на нём, затем возьми и бесплатно сыграй любое существо из твоего сброса или сброса противника"}]'::jsonb, 'исходники/карты/lich_card_37.png', 'undead', false),
  (39, 'Убей-молния', 'Нанеси урон по цепочке трём существам противника на соседних землях. Первому наносится 3 урона, второму - 2 и третьему - 1.', 'заклинание', 2, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lich_card_39.png', 'rainbow', true),
  (40, 'Кровавая крепость', 'Твоё существо на этой линии получает +1 АТК.', 'здание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lich_card_40.png', 'rainbow', true),
  (42, 'Могищи', '+2 ATK на этом ходу существу с наименьшим значением ATK из существ под твоим контролем, находящихся в игре. Если таких несколько, применяй на любое из них.', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"применяй на любое из них"}],"conditions":[{"type":"if","description":"таких несколько"}],"description":"применяй на любое из них","source_text":"Если таких несколько, применяй на любое из них"}]'::jsonb, 'исходники/карты/lich_card_42.png', 'rainbow', true),
  (43, 'Неразборчивый гладиатор', 'Не отличает своих от чужих. При атаке существ противника, если рядом с ним есть союзные существа, нанеси одному из них на твой выбор 2 урона.', 'существо', 1, 4, 3, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"нанеси одному из них на твой выбор 2 урона"}],"conditions":[{"type":"if","description":"рядом с ним есть союзные существа"}],"description":"нанеси одному из них на твой выбор 2 урона","source_text":"если рядом с ним есть союзные существа, нанеси одному из них на твой выбор 2 урона"}]'::jsonb, 'исходники/карты/lich_card_43.png', 'undead', false),
  (44, 'Очаровательный трупоглик', 'Питается павшими.
Приём >>> Уничтожь верхнюю карту сброса противника и получи постоянно +1 АТК.
Положи эту карту под него, сбрось все при смерти.', 'существо', 2, 1, 9, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Положи","target":"none","effect":"эту карту под него, сбрось все при смерти"}],"conditions":[{"type":"verb","value":"Положи"}],"description":"эту карту под него, сбрось все при смерти","source_text":"Положи эту карту под него, сбрось все при смерти"}]'::jsonb, 'исходники/карты/lich_card_44.png', 'undead', false),
  (46, 'Чудесная жертва', 'Уничтожь существо под твоим контролем. Если урон на нём - меньше половины его DEF, тяни 3 карты, иначе можешь взять 2.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"conditional","actions":[{"type":"draw_cards","target":"none","count":3,"source":"deck"}],"conditions":[{"type":"if","description":"урон на нём - меньше половины его DEF"}],"description":"тяни 3 карты, иначе можешь взять 2","source_text":"Если урон на нём - меньше половины его DEF, тяни 3 карты, иначе можешь взять 2"},{"trigger":"manual","actions":[{"type":"destroy","target":"none","count":1}],"conditions":[{"type":"verb","value":"Уничтожь"}],"description":"существо под твоим контролем","source_text":"Уничтожь существо под твоим контролем"}]'::jsonb, 'исходники/карты/lich_card_46.png', 'undead', false),
  (48, 'Муррризрак', 'Считается призрачным и милым существом одновременно. Кошачьи жизни: после уничтожения может быть воскрешен с полными жизнями (только 1 раз, по желанию). После этого нельзя вернуть из сброса.', 'существо', 1, 1, 4, false, '', '[]'::jsonb, 'исходники/карты/lich_card_48.png', 'undead', false),
  (5, 'Проклятый древесный дух', 'Начиная со следующего твоего хода каждый ход получает +1 DEF навсегда. Существа противника на этой линии без урона на них, видя дух, паникуют и теряют -1 ATK.', 'существо', 2, 2, 8, false, '', '[{"trigger":"persistent","actions":[{"type":"stat_buff","target":"each_creature","stat":"defense","amount":1,"duration":"persistent"}],"conditions":[],"description":"каждый ход получает +1 DEF","source_text":"каждый ход получает +1 DEF"}]'::jsonb, 'исходники/карты/lich_card_5.png', 'undead', false),
  (6, 'Частичка души', 'Когда играешь Частичку из руки, можешь тут же сыграть вторую из колоды (если она там есть), после перемешай. Если поле покидает одна, с ней уходит и вторая. Нельзя вернуть из сброса.', 'существо', 1, 2, 4, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"после перемешай"}],"conditions":[{"type":"if","description":"она там есть)"}],"description":"после перемешай","source_text":"если она там есть), после перемешай"},{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"с ней уходит и вторая"}],"conditions":[{"type":"if","description":"поле покидает одна"}],"description":"с ней уходит и вторая","source_text":"Если поле покидает одна, с ней уходит и вторая"}]'::jsonb, 'исходники/карты/lich_card_6.png', 'undead', false),
  (8, 'Прозрачный ниндзя', 'Когда Прозрачный ниндзя атакован другим существом (но не заклинанием или приёмом), у него есть шанс избежать атаки. Кидай кубик, на 4 и больше урон не прошёл.', 'существо', 1, 2, 5, false, '', '[]'::jsonb, 'исходники/карты/lich_card_8.png', 'undead', false),
  (1, 'Мавзолей', 'Твое Существо на этой линии получает +1 DEF за каждые 5 карт в твоей стопке сброса.', 'здание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lsp_card_1.png', 'swamp', false),
  (10, 'Беспредельная фигура', 'Сбрось карту >>> Нанеси 1 урон другому существу на этой линии. (Используй любое количество раз в каждый свой ход.)', 'существо', 1, 1, 6, false, '', '[{"trigger":"manual","actions":[{"type":"deal_damage","target":"each_creature_in_lane","amount":1,"pierce":false}],"conditions":[{"type":"verb","value":"Сбрось"}],"description":"карту >>> Нанеси 1 урон другому существу на этой линии. (Используй любое количество раз в каждый свой ход.)","source_text":"Сбрось карту >>> Нанеси 1 урон другому существу на этой линии. (Используй любое количество раз в каждый свой ход.)"}]'::jsonb, 'исходники/карты/lsp_card_10.png', 'swamp', false),
  (12, 'Розовая сирена', 'Сбрось карту >>> Нанеси 1 Урон каждому существу противника. (Используй только один раз в каждый свой ход.)', 'существо', 2, 2, 8, false, '', '[{"trigger":"manual","actions":[{"type":"deal_damage","target":"each_creature_opponent","amount":1,"pierce":false}],"conditions":[{"type":"verb","value":"Сбрось"}],"description":"карту >>> Нанеси 1 Урон каждому существу противника. (Используй только один раз в каждый свой ход.)","source_text":"Сбрось карту >>> Нанеси 1 Урон каждому существу противника. (Используй только один раз в каждый свой ход.)"}]'::jsonb, 'исходники/карты/lsp_card_12.png', 'swamp', false),
  (13, 'Костяная рука', 'ПРИЕМ >>> Сбрось 3 верхние карты своей колоды. За каждое заклинание сброшенное таким образом, выбранный игрок сбрасывает карту.', 'существо', 2, 3, 6, false, '', '[{"trigger":"manual","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"cost_actions","value":1}],"description":"Сбрось 3 верхние карты своей колоды","source_text":"ПРИЕМ >>> Сбрось 3 верхние карты своей колоды"}]'::jsonb, 'исходники/карты/lsp_card_13.png', 'swamp', false),
  (14, 'Лысый заседатель', 'Сбрось карту >>> Восстанови 1 Урон с Лысого заседателя. (Используй только один раз в каждый свой ход.)', 'существо', 1, 2, 7, false, '', '[{"trigger":"manual","actions":[{"type":"heal","target":"each_creature_yours","amount":1,"cap":25}],"conditions":[{"type":"verb","value":"Сбрось"}],"description":"карту >>> Восстанови 1 Урон с Лысого заседателя. (Используй только один раз в каждый свой ход.)","source_text":"Сбрось карту >>> Восстанови 1 Урон с Лысого заседателя. (Используй только один раз в каждый свой ход.)"}]'::jsonb, 'исходники/карты/lsp_card_14.png', 'swamp', false),
  (16, 'Рубленный стейк', 'В начале твоего хода сбрось 2 карты или уничтожь Рубленный стейк. (Сброс после начального взятия карты.)', 'существо', 1, 4, 4, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[],"description":"В начале твоего хода сбрось 2 карты или уничтожь Рубленный стейк","source_text":"В начале твоего хода сбрось 2 карты или уничтожь Рубленный стейк"}]'::jsonb, 'исходники/карты/lsp_card_16.png', 'swamp', false),
  (17, 'Пирамида', 'ПРИЕМ >>> Если контролируешь существо на этой линии, получи 1 действие. Используй его только чтобы играть существо на эту линию.', 'здание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"gain_actions","target":"none","count":1}],"conditions":[{"type":"cost_actions","value":1}],"description":"Если контролируешь существо на этой линии, получи 1 действие","source_text":"ПРИЕМ >>> Если контролируешь существо на этой линии, получи 1 действие"},{"trigger":"conditional","actions":[{"type":"gain_actions","target":"none","count":1}],"conditions":[{"type":"if","description":"контролируешь существо на этой линии"}],"description":"получи 1 действие","source_text":"Если контролируешь существо на этой линии, получи 1 действие"}]'::jsonb, 'исходники/карты/lsp_card_17.png', 'plains', false),
  (18, 'Кристалл силы', 'Выбранный игрок тянет 5 карт.', 'заклинание', 2, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lsp_card_18.png', 'plains', false),
  (20, 'Сила подсознания', 'Выбранное существо под твоим контролем получает +2 АТК в этот ход, за каждое заклинание (включая это) сыгранное тобой в этот ход.', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lsp_card_20.png', 'plains', false),
  (2, 'Тёмный маяк', 'ПРИЕМ >>> Если у противника нет существа на этой линии, то он сбрасывает карту.', 'здание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"manual","target":"none","effect":"Если у противника нет существа на этой линии, то он сбрасывает кар"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Если у противника нет существа на этой линии, то он сбрасывает кар","source_text":"ПРИЕМ >>> Если у противника нет существа на этой линии, то он сбрасывает кар"},{"trigger":"conditional","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"if","description":"у противника нет существа на этой линии"}],"description":"он сбрасывает карту","source_text":"Если у противника нет существа на этой линии, то он сбрасывает карту"}]'::jsonb, 'исходники/карты/lsp_card_2.png', 'swamp', false),
  (21, 'Офицительные штаны', 'Перемести выбранное существо под твоим контролем на пустую Голубую равнину под твоим контролем, затем тяни карту.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"},{"type":"draw_cards","target":"none","count":1,"source":"deck"}],"conditions":[{"type":"verb","value":"Перемести"}],"description":"выбранное существо под твоим контролем на пустую Голубую равнину под твоим контролем, затем тяни карту","source_text":"Перемести выбранное существо под твоим контролем на пустую Голубую равнину под твоим контролем, затем тяни карту"}]'::jsonb, 'исходники/карты/lsp_card_21.png', 'plains', false),
  (22, 'Скелет гастролёр', 'ПРИЕМ >>> Скелет гастролёр и другое существо под твоим контролем меняются линиями друг с другом.', 'существо', 1, 0, 8, false, '', '[{"trigger":"manual","actions":[{"type":"manual","target":"none","effect":"Скелет гастролёр и другое существо под твоим контролем меняются линиями друг с друг"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Скелет гастролёр и другое существо под твоим контролем меняются линиями друг с друг","source_text":"ПРИЕМ >>> Скелет гастролёр и другое существо под твоим контролем меняются линиями друг с друг"}]'::jsonb, 'исходники/карты/lsp_card_22.png', 'plains', false),
  (23, 'Черничная Джинни', 'Когда Черничная Джинни вступает в игру заменяя существо, тяни две карты.', 'существо', 1, 2, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"passive","target":"none","effect":"заменяя существо, тяни две карты"}],"conditions":[],"description":"заменяя существо, тяни две карты","source_text":"Когда Черничная Джинни вступает в игру заменяя существо, тяни две карты"}]'::jsonb, 'исходники/карты/lsp_card_23.png', 'plains', false),
  (25, 'Виноградная Джинни', 'Когда Виноградная Джинни вступает в игру заменяя существо, можешь положить карту из стопки сброса на верх своей колоды.', 'существо', 1, 1, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"draw_cards","target":"none","filter":"any","count":1,"source":"discard_pile"}],"conditions":[],"description":"заменяя существо, можешь положить карту из стопки сброса на верх своей колоды","source_text":"Когда Виноградная Джинни вступает в игру заменяя существо, можешь положить карту из стопки сброса на верх своей колоды"}]'::jsonb, 'исходники/карты/lsp_card_25.png', 'plains', false),
  (27, 'Липкий мозг', 'Когда Липкий мозг вступает в игру заменяя существо, он получает +2 ATK в этот ход.', 'существо', 1, 1, 7, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"passive","target":"none","effect":"заменяя существо, он получает +2 ATK в этот ход"}],"conditions":[],"description":"заменяя существо, он получает +2 ATK в этот ход","source_text":"Когда Липкий мозг вступает в игру заменяя существо, он получает +2 ATK в этот ход"}]'::jsonb, 'исходники/карты/lsp_card_27.png', 'plains', false),
  (29, 'Школяр будущего', 'Когда Школяр будущего вступает в игру заменяя существо, получи 1 Действие.', 'существо', 2, 2, 8, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"gain_actions","target":"none","count":1}],"conditions":[],"description":"заменяя существо, получи 1 Действие","source_text":"Когда Школяр будущего вступает в игру заменяя существо, получи 1 Действие"}]'::jsonb, 'исходники/карты/lsp_card_29.png', 'plains', false),
  (3, 'Унитаз апокалипсиса', 'Выбранное существо под твоим контролем получает +1 ATK в этот ход за каждые 5 карт в твоей стопке сброса.', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lsp_card_3.png', 'swamp', false),
  (31, 'Тупица в наушниках', 'Когда Тупица в наушниках вступает в игру заменяя существо, нанеси 3 урона другому существу на этой линии.', 'существо', 2, 2, 7, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"deal_damage","target":"this_creature","amount":3,"pierce":false}],"conditions":[],"description":"заменяя существо, нанеси 3 урона другому существу на этой линии","source_text":"Когда Тупица в наушниках вступает в игру заменяя существо, нанеси 3 урона другому существу на этой линии"}]'::jsonb, 'исходники/карты/lsp_card_31.png', 'plains', true),
  (32, 'Рубленый стейк', 'В начале твоего хода сбрось 2 карты или уничтожь Рубленый стейк. (Сбрось после начального взятия карты.)', 'существо', 1, 4, 4, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[],"description":"В начале твоего хода сбрось 2 карты или уничтожь Рубленый стейк","source_text":"В начале твоего хода сбрось 2 карты или уничтожь Рубленый стейк"}]'::jsonb, 'исходники/карты/lsp_card_32.png', 'swamp', false),
  (34, 'Козел', 'Когда Козел вступает в игру заменяя существо, тяни карту.', 'существо', 0, 1, 4, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"draw_cards","target":"none","count":1,"source":"deck"}],"conditions":[],"description":"заменяя существо, тяни карту","source_text":"Когда Козел вступает в игру заменяя существо, тяни карту"}]'::jsonb, 'исходники/карты/lsp_card_34.png', 'rainbow', true),
  (35, 'Хороший песик', 'Сбрось карту >>> Хороший песик получает +2 АТК в этом ходу. (Используй только один раз в каждый свой ход.)', 'существо', 0, 0, 5, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"stat_buff","target":"this_creature","stat":"attack","amount":2,"duration":"this_turn"}],"conditions":[],"description":"получает +2 АТК в этом ходу","source_text":"получает +2 АТК в этом ходу"},{"trigger":"manual","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"verb","value":"Сбрось"}],"description":"карту >>> Хороший песик получает +2 АТК в этом ходу. (Используй только один раз в каждый свой ход.)","source_text":"Сбрось карту >>> Хороший песик получает +2 АТК в этом ходу. (Используй только один раз в каждый свой ход.)"}]'::jsonb, 'исходники/карты/lsp_card_35.png', 'rainbow', true),
  (37, 'Сила трусов', 'Выбранное Болотное существо под твоим контролем получает +2 ATK в этом ход.', 'заклинание', 0, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/lsp_card_37.png', 'rainbow', true),
  (39, 'Вулкан', 'Уничтожь выбранное строение. Можешь нанести 3 урона существу на этой линии. Переверни лицом вниз свою землю на этой линии.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"destroy","target":"none","count":1}],"conditions":[{"type":"verb","value":"Уничтожь"}],"description":"выбранное строение","source_text":"Уничтожь выбранное строение"}]'::jsonb, 'исходники/карты/lsp_card_39.png', 'rainbow', true),
  (4, 'Нога дракона', 'Сбрось карту >>> Нога дракона получает +1 ATK в этот ход. (Используй до 5 раз во время своего каждого хода.)', 'существо', 1, 1, 5, false, '', '[{"trigger":"manual","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"verb","value":"Сбрось"}],"description":"карту >>> Нога дракона получает +1 ATK в этот ход. (Используй до 5 раз во время своего каждого хода.)","source_text":"Сбрось карту >>> Нога дракона получает +1 ATK в этот ход. (Используй до 5 раз во время своего каждого хода.)"}]'::jsonb, 'исходники/карты/lsp_card_4.png', 'swamp', false),
  (6, 'Гусенничка', '+2 ATK за каждые 5 карт в твоей стопке сброса.', 'существо', 2, 0, 3, false, '', '[]'::jsonb, 'исходники/карты/lsp_card_6.png', 'swamp', false),
  (7, 'Гусеничка', '+2 ATK за каждые 5 карт в твоей стопке сброса.', 'существо', 2, 0, 3, false, '', '[]'::jsonb, 'исходники/карты/lsp_card_7.png', 'swamp', false),
  (8, 'Геркулаз', 'Сбрось карту >>> Геркулаз получает +4 ATK в этом ход. (Используй только один раз в каждый свой ход.)', 'существо', 2, 1, 6, false, '', '[{"trigger":"manual","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"verb","value":"Сбрось"}],"description":"карту >>> Геркулаз получает +4 ATK в этом ход. (Используй только один раз в каждый свой ход.)","source_text":"Сбрось карту >>> Геркулаз получает +4 ATK в этом ход. (Используй только один раз в каждый свой ход.)"}]'::jsonb, 'исходники/карты/lsp_card_8.png', 'swamp', false),
  (1, 'Загробный дом', 'Когда враг сбрасывает карту, твоё существо на этой линии получает +1 ATK до конца следующего хода.', 'здание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/marceline_card_1.png', 'swamp', false),
  (10, 'Муика-хлопушка', 'ПРИЕМ >>> Каждый противник сбрасывает карту стоимостью 0 или показывает руку, если их нет.', 'существо', 1, 1, 6, false, '', '[{"trigger":"manual","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"cost_actions","value":1}],"description":"Каждый противник сбрасывает карту стоимостью 0 или показывает руку, если их н","source_text":"ПРИЕМ >>> Каждый противник сбрасывает карту стоимостью 0 или показывает руку, если их н"}]'::jsonb, 'исходники/карты/marceline_card_10.png', 'swamp', false),
  (11, 'Принцесса Банши', 'Когда Принцесса Банши вступает в игру, можешь убрать жетон с соседней земли.', 'существо', 1, 2, 7, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"passive","target":"none","effect":"можешь убрать жетон с соседней земли"}],"conditions":[],"description":"можешь убрать жетон с соседней земли","source_text":"Когда Принцесса Банши вступает в игру, можешь убрать жетон с соседней земли"}]'::jsonb, 'исходники/карты/marceline_card_11.png', 'swamp', false),
  (13, 'Королева Банши', 'Когда Королева Банши вступает в игру, можешь удалить жетон с соседней земли.', 'существо', 2, 3, 9, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"passive","target":"none","effect":"можешь удалить жетон с соседней земли"}],"conditions":[],"description":"можешь удалить жетон с соседней земли","source_text":"Когда Королева Банши вступает в игру, можешь удалить жетон с соседней земли"}]'::jsonb, 'исходники/карты/marceline_card_13.png', 'swamp', false),
  (14, 'Ангел-болом Банши', 'Потрать 1 Действие >>> Перемести весь урон с этого существа на выбранное существо.', 'существо', 2, 2, 7, false, '', '[]'::jsonb, 'исходники/карты/marceline_card_14.png', 'swamp', false),
  (15, 'Ведьмак', 'Когда враг сбрасывает карту, нанеси ему 1 Урон..', 'существо', 2, 1, 11, false, '', '[]'::jsonb, 'исходники/карты/marceline_card_15.png', 'swamp', false),
  (17, 'Бездомный болот', 'Если Бездомный болот покидает игру, пока подготовлен, каждый противник сбрасывает карту.', 'существо', 1, 2, 6, false, '', '[{"trigger":"conditional","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"if","description":"Бездомный болот покидает игру"}],"description":"пока подготовлен, каждый противник сбрасывает карту","source_text":"Если Бездомный болот покидает игру, пока подготовлен, каждый противник сбрасывает карту"},{"trigger":"persistent","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"while","description":"подготовлен"}],"description":"каждый противник сбрасывает карту","source_text":"пока подготовлен, каждый противник сбрасывает карту"}]'::jsonb, 'исходники/карты/marceline_card_17.png', 'swamp', false),
  (19, 'Болотная бомба-лягушка', 'Если Болотная бомба-лягушка покидает игру пока подготовлена, нанеси 2 урона каждому существу противника.', 'существо', 2, 3, 8, false, '', '[{"trigger":"conditional","actions":[{"type":"deal_damage","target":"each_creature_opponent","amount":2,"pierce":false}],"conditions":[{"type":"if","description":"Болотная бомба-лягушка покидает игру пока подготовлена"}],"description":"нанеси 2 урона каждому существу противника","source_text":"Если Болотная бомба-лягушка покидает игру пока подготовлена, нанеси 2 урона каждому существу противника"},{"trigger":"persistent","actions":[{"type":"deal_damage","target":"each_creature_opponent","amount":2,"pierce":false}],"conditions":[{"type":"while","description":"подготовлена"}],"description":"нанеси 2 урона каждому существу противника","source_text":"пока подготовлена, нанеси 2 урона каждому существу противника"}]'::jsonb, 'исходники/карты/marceline_card_19.png', 'swamp', false),
  (2, 'Картонный особняк', 'Картонный особняк стоит на 1 меньше за каждые 5 карт в твоей стопке сброса. ПРИЕМ >>> Получи 1 действие.', 'здание', 5, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"gain_actions","target":"none","count":1}],"conditions":[{"type":"cost_actions","value":1}],"description":"Получи 1 действ","source_text":"ПРИЕМ >>> Получи 1 действ"}]'::jsonb, 'исходники/карты/marceline_card_2.png', 'swamp', false),
  (20, 'Док Куколыптейн', 'ПРИЕМ >>> Восстанови 2 урона с существа на соседней линии. Если на Доке Куколыптейне 5 или более урона, то вместо этого восстанови 2 урона с каждого существа.', 'существо', 2, 1, 9, false, '', '[{"trigger":"manual","actions":[{"type":"heal","target":"adjacent_creature","amount":2,"cap":25}],"conditions":[{"type":"cost_actions","value":1}],"description":"Восстанови 2 урона с существа на соседней линии","source_text":"ПРИЕМ >>> Восстанови 2 урона с существа на соседней линии"},{"trigger":"conditional","actions":[{"type":"heal","target":"each_creature_yours","amount":2,"cap":25}],"conditions":[{"type":"if","description":"на Доке Куколыптейне 5 или более урона"}],"description":"вместо этого восстанови 2 урона с каждого существа","source_text":"Если на Доке Куколыптейне 5 или более урона, то вместо этого восстанови 2 урона с каждого существа"}]'::jsonb, 'исходники/карты/marceline_card_20.png', 'cute', false),
  (21, 'Док Кукольштейн', 'ПРИЕМ >>> Восстанови 2 урона с существа на соседней линии. Если на Доке Кукольштейне 5 или более урона, то вместо этого восстанови 2 урона с каждого существа.', 'существо', 2, 1, 9, false, '', '[{"trigger":"manual","actions":[{"type":"heal","target":"adjacent_creature","amount":2,"cap":25}],"conditions":[{"type":"cost_actions","value":1}],"description":"Восстанови 2 урона с существа на соседней линии","source_text":"ПРИЕМ >>> Восстанови 2 урона с существа на соседней линии"},{"trigger":"conditional","actions":[{"type":"heal","target":"each_creature_yours","amount":2,"cap":25}],"conditions":[{"type":"if","description":"на Доке Кукольштейне 5 или более урона"}],"description":"вместо этого восстанови 2 урона с каждого существа","source_text":"Если на Доке Кукольштейне 5 или более урона, то вместо этого восстанови 2 урона с каждого существа"}]'::jsonb, 'исходники/карты/marceline_card_21.png', 'cute', false),
  (22, 'Хлопкопульт', 'ПРИЕМ >>> Нанеси 1 урон выбранному существу. Если на Хлопкопульте 5 урона или более, она восстанавливает 1 урон и подготавливается.', 'существо', 1, 1, 8, false, '', '[{"trigger":"manual","actions":[{"type":"deal_damage","target":"chosen_creature","amount":1,"pierce":false}],"conditions":[{"type":"cost_actions","value":1}],"description":"Нанеси 1 урон выбранному существу","source_text":"ПРИЕМ >>> Нанеси 1 урон выбранному существу"},{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"она восстанавливает 1 урон и подготавливается"}],"conditions":[{"type":"if","description":"на Хлопкопульте 5 урона или более"}],"description":"она восстанавливает 1 урон и подготавливается","source_text":"Если на Хлопкопульте 5 урона или более, она восстанавливает 1 урон и подготавливается"}]'::jsonb, 'исходники/карты/marceline_card_22.png', 'cute', false),
  (24, 'Яростная наседка', 'Яростная цыпа получает +1 АТК за каждую единицу урона на ней.', 'существо', 2, 0, 10, false, '', '[]'::jsonb, 'исходники/карты/marceline_card_24.png', 'cute', false),
  (25, 'Большой курятник', 'В начале твоего хода нанеси 1 или 2 Урона своему существу на этой линии, затем восстанови 1 HP (максимум 25).', 'здание', 1, NULL, NULL, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"heal","target":"each_creature_yours","amount":1,"cap":25}],"conditions":[],"description":"В начале твоего хода нанеси 1 или 2 Урона своему существу на этой линии, затем восстанови 1 HP (максимум 25)","source_text":"В начале твоего хода нанеси 1 или 2 Урона своему существу на этой линии, затем восстанови 1 HP (максимум 25)"}]'::jsonb, 'исходники/карты/marceline_card_25.png', 'cute', false),
  (26, 'Авто-ощипыватель', 'ПРИЕМ >>> Восстанови или нанеси 1 урон своему существу на этой линии.', 'здание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"deal_damage","target":"this_creature","amount":1,"pierce":false}],"conditions":[{"type":"cost_actions","value":1}],"description":"Восстанови или нанеси 1 урон своему существу на этой лин","source_text":"ПРИЕМ >>> Восстанови или нанеси 1 урон своему существу на этой лин"}]'::jsonb, 'исходники/карты/marceline_card_26.png', 'cute', false),
  (27, 'Пентапластырь', 'Восстанови ровно 5 урона с существа под твоим контролем (ни больше, ни меньше).', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Восстанови","target":"none","effect":"ровно 5 урона с существа под твоим контролем (ни больше, ни меньше)"}],"conditions":[{"type":"verb","value":"Восстанови"}],"description":"ровно 5 урона с существа под твоим контролем (ни больше, ни меньше)","source_text":"Восстанови ровно 5 урона с существа под твоим контролем (ни больше, ни меньше)"}]'::jsonb, 'исходники/карты/marceline_card_27.png', 'cute', false),
  (29, 'Утка-менестрель', 'ПРИЦЕП >>> Тяни карту. Если у Утки-менестреля 5 или более урона, то тяни еще одну.', 'существо', 1, 0, 9, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"тяни еще одну"}],"conditions":[{"type":"if","description":"у Утки-менестреля 5 или более урона"}],"description":"тяни еще одну","source_text":"Если у Утки-менестреля 5 или более урона, то тяни еще одну"}]'::jsonb, 'исходники/карты/marceline_card_29.png', 'cute', false),
  (3, 'Ванна крови', 'Выбранный брас сбрасывает карту стоимостью 2 или более. Если нет, то нанеси 5 урона этому врагу.', 'заклинание', 2, NULL, NULL, false, '', '[{"trigger":"conditional","actions":[{"type":"deal_damage","target":"none","amount":5,"pierce":false}],"conditions":[{"type":"if","description":"нет"}],"description":"нанеси 5 урона этому врагу","source_text":"Если нет, то нанеси 5 урона этому врагу"}]'::jsonb, 'исходники/карты/marceline_card_3.png', 'swamp', false),
  (31, 'Бумажный тигр', 'Пока на Бумажном тигре ровно 5 урона, он получает +5 АТК.', 'существо', 2, 2, 9, false, '', '[{"trigger":"persistent","actions":[{"type":"passive","target":"none","effect":"он получает +5 АТК"}],"conditions":[{"type":"while","description":"на Бумажном тигре ровно 5 урона"}],"description":"он получает +5 АТК","source_text":"Пока на Бумажном тигре ровно 5 урона, он получает +5 АТК"}]'::jsonb, 'исходники/карты/marceline_card_31.png', 'cute', false),
  (33, 'Ожерелье черных дыр', 'Выбранное существо получает X ATK в этом ход, где X это число различных типов земель под контролем твоего противника.', 'заклинание', 0, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/marceline_card_33.png', 'rainbow', true),
  (35, 'Переливание крови', 'Удали из игры карту из любой стопки сброса игроков. Восстанови X урона с выбранного существа, где X стоимость карты изъятой этим способом.', 'заклинание', 0, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/marceline_card_35.png', 'rainbow', true),
  (36, 'Яростная цыпа', 'Яростная цыпа получает +1 ATK за каждый урон на ней.', 'существо', 0, 0, 5, false, '', '[]'::jsonb, 'исходники/карты/marceline_card_36.png', 'rainbow', true),
  (39, 'Яростный петух', 'Яростный петух получает +1 ATK за каждую единицу урона на нем.', 'существо', 1, 0, 8, false, '', '[]'::jsonb, 'исходники/карты/marceline_card_39.png', 'cute', false),
  (5, 'Белкобомбы!', 'Выбранный враг может сбросить карту. Если нет, то нанеси 2 Урона каждому его существу.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"conditional","actions":[{"type":"deal_damage","target":"each_creature","amount":2,"pierce":false}],"conditions":[{"type":"if","description":"нет"}],"description":"нанеси 2 Урона каждому его существу","source_text":"Если нет, то нанеси 2 Урона каждому его существу"}]'::jsonb, 'исходники/карты/marceline_card_5.png', 'swamp', false),
  (7, 'Уницклоп', 'В начале твоего хода каждый игрок тянет карту и затем сбрасывает карту.', 'существо', 2, 1, 10, false, '', '[{"trigger":"start_of_turn","actions":[{"type":"draw_cards","target":"none","count":1,"source":"deck"},{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[],"description":"В начале твоего хода каждый игрок тянет карту и затем сбрасывает карту","source_text":"В начале твоего хода каждый игрок тянет карту и затем сбрасывает карту"}]'::jsonb, 'исходники/карты/marceline_card_7.png', 'swamp', false),
  (1, 'Пакость', 'Выбери двух игроков. Каждый открывает случайную карту с руки. Если их стоимость не совпадает они сбрасывают эти карты.', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Выбери","target":"none","effect":"двух игроков"}],"conditions":[{"type":"verb","value":"Выбери"}],"description":"двух игроков","source_text":"Выбери двух игроков"}]'::jsonb, 'исходники/карты/monika_card_1.png', 'rainbow', true),
  (10, 'Ледяная бомбардировка', 'Уничтожь выбранное существо на земле с Ледяным жетоном.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"destroy","target":"chosen_creature","count":1}],"conditions":[{"type":"verb","value":"Уничтожь"}],"description":"выбранное существо на земле с Ледяным жетоном","source_text":"Уничтожь выбранное существо на земле с Ледяным жетоном"}]'::jsonb, 'исходники/карты/monika_card_10.png', 'ice', true),
  (11, 'Ледяной залп', 'Заморозь выбранную землю. Ты можешь перемещать любое количество ледяных жетонов на новые земли (1 жетон на землю).', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/monika_card_11.png', 'ice', false),
  (12, 'Бригадир десерт', 'Когда Бригадир десерт атакует, нанеси 2 урона выбранному Существу противника на замле с Ледяным жетоном.', 'существо', 2, 3, 9, false, '', '[{"trigger":"on_creature_attacks","actions":[{"type":"deal_damage","target":"chosen_opponent","amount":2,"pierce":false}],"conditions":[],"description":", нанеси 2 урона выбранному Существу противника на замле с Ледяным жетоном","source_text":"Когда Бригадир десерт атакует, нанеси 2 урона выбранному Существу противника на замле с Ледяным жетоном"}]'::jsonb, 'исходники/карты/monika_card_12.png', 'ice', false),
  (13, 'Офицер ириска', 'Каждый раз когда земля замораживается, тяни карту.', 'существо', 2, 2, 9, false, '', '[]'::jsonb, 'исходники/карты/monika_card_13.png', 'ice', false),
  (14, 'Капитан мороженка', 'Капитан мороженка стоит на 1 меньше за каждого игрока чьи земли с Ледяным жетоном.', 'существо', 4, 4, 8, false, '', '[]'::jsonb, 'исходники/карты/monika_card_14.png', 'ice', false),
  (2, 'Один в один', 'Вытяни 2 верхних карты из своей колоды. Если они одинаковой стоимости нанеси урон выбранному противнику. Как сделал это, можешь вложить эту карту в руку партнёра.', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/monika_card_2.png', 'rainbow', true),
  (20, 'Замороженный патрилег', 'Когда Замороженный патрилег вступает в игру, можешь Заморозить Землю на этой линии.', 'существо', 1, 1, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"freeze_landscape","target":"chosen_landscape"}],"conditions":[],"description":"можешь Заморозить Землю на этой линии","source_text":"Когда Замороженный патрилег вступает в игру, можешь Заморозить Землю на этой линии"}]'::jsonb, 'исходники/карты/monika_card_20.png', 'ice', true),
  (24, 'Поддержка', 'Пока ты или твой партнёр контролируете существо на земле с ледяным жетоном, ваша команда может играть существ на земли с ледяным жетоном.', 'special', 1, NULL, NULL, false, '', '[{"trigger":"persistent","actions":[{"type":"passive","target":"none","effect":"ваша команда может играть существ на земли с ледяным жетоном"}],"conditions":[{"type":"while","description":"ты или твой партнёр контролируете существо на земле с ледяным жетоном"}],"description":"ваша команда может играть существ на земли с ледяным жетоном","source_text":"Пока ты или твой партнёр контролируете существо на земле с ледяным жетоном, ваша команда может играть существ на земли с ледяным жетоном"}]'::jsonb, 'исходники/карты/monika_card_24.png', 'ice', false),
  (25, 'Крок-каскадер', 'Когда Крок-каскадер вступает в игру, тяни карту за каждое существо, которое отправилось в сброс в этом ходу.', 'существо', 1, 2, 6, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"draw_cards","target":"none","count":1,"source":"deck"}],"conditions":[],"description":"тяни карту за каждое существо, которое отправилось в сброс в этом ходу","source_text":"Когда Крок-каскадер вступает в игру, тяни карту за каждое существо, которое отправилось в сброс в этом ходу"}]'::jsonb, 'исходники/карты/monika_card_25.png', 'swamp', false),
  (26, 'Крок-поработитель', 'Существо противника на этой линии получает -1 DEF за каждые 5 карт в твоей стопке сброса.', 'существо', 2, 3, 7, false, '', '[]'::jsonb, 'исходники/карты/monika_card_26.png', 'swamp', false),
  (28, 'Крок-исследователь', 'Сбрось карту >>> Крок-исследователь получает +ATK равную стоимости сброшенной карты (используй только во время своего хода).', 'существо', 1, 2, 6, false, '', '[{"trigger":"manual","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"verb","value":"Сбрось"}],"description":"карту >>> Крок-исследователь получает +ATK равную стоимости сброшенной карты (используй только во время своего хода)","source_text":"Сбрось карту >>> Крок-исследователь получает +ATK равную стоимости сброшенной карты (используй только во время своего хода)"}]'::jsonb, 'исходники/карты/monika_card_28.png', 'swamp', false),
  (30, 'Крок-эколог', 'Когда Крок-эколог на Ледяной земле, он получает +2 ATK.', 'существо', 1, 1, 5, false, '', '[]'::jsonb, 'исходники/карты/monika_card_30.png', 'swamp', false),
  (32, 'Крок-детектив', 'Сбрось карту >>> Открой 3 верхние карты своей колоды. Сыграй открытое партнёрство бесплатно, затем сбрось другие карты.', 'существо', 2, 3, 8, false, '', '[{"trigger":"manual","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"verb","value":"Сбрось"}],"description":"карту >>> Открой 3 верхние карты своей колоды","source_text":"Сбрось карту >>> Открой 3 верхние карты своей колоды"}]'::jsonb, 'исходники/карты/monika_card_32.png', 'swamp', false),
  (33, 'Крок-зачинщик', 'Когда Крок-зачинщик вступает в игру, передвинь выбранное существо противника на линию Крок-зачинщика (если она пуста).', 'существо', 2, 5, 3, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"passive","target":"none","effect":"передвинь выбранное существо противника на линию Крок-зачинщика (если она пуста)"}],"conditions":[],"description":"передвинь выбранное существо противника на линию Крок-зачинщика (если она пуста)","source_text":"Когда Крок-зачинщик вступает в игру, передвинь выбранное существо противника на линию Крок-зачинщика (если она пуста)"}]'::jsonb, 'исходники/карты/monika_card_33.png', 'swamp', false),
  (34, 'Крок-дезинсектор', 'Потрать 1 Действие, ПРИЦЕМ >>> Нанеси 1 урон каждому существу противника в игре.', 'существо', 1, 1, 6, false, '', '[]'::jsonb, 'исходники/карты/monika_card_34.png', 'swamp', false),
  (35, 'Тошнотный клоп', 'Уничтожь Тошнотного клопа >>> Уничтожь выбранное Существо противника на этой линии и любое существо с таким же именем в игре.', 'существо', 2, 2, 6, false, '', '[{"trigger":"manual","actions":[{"type":"destroy","target":"chosen_opponent_creature","count":1}],"conditions":[{"type":"verb","value":"Уничтожь"}],"description":"Тошнотного клопа >>> Уничтожь выбранное Существо противника на этой линии и любое существо с таким же именем в игре","source_text":"Уничтожь Тошнотного клопа >>> Уничтожь выбранное Существо противника на этой линии и любое существо с таким же именем в игре"}]'::jsonb, 'исходники/карты/monika_card_35.png', 'swamp', false),
  (37, 'Затопление', 'Существа противника получают -2 ATK в этот ход (минимум 0).', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/monika_card_37.png', 'swamp', false),
  (38, 'Посох Буду', 'Наноси урон выбранному существу пока у него не остается 1 DEF.', 'заклинание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/monika_card_38.png', 'swamp', false),
  (39, 'Гнилой фонтан', 'Сбрось карту >>> Твое Существо на этой линии получает +1 ATK в этот ход. (Используй любое количество раз во время своего хода).', 'здание', 1, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"discard_cards","target":"none","count":1,"source":"hand","random":false}],"conditions":[{"type":"verb","value":"Сбрось"}],"description":"карту >>> Твое Существо на этой линии получает +1 ATK в этот ход. (Используй любое количество раз во время своего хода)","source_text":"Сбрось карту >>> Твое Существо на этой линии получает +1 ATK в этот ход. (Используй любое количество раз во время своего хода)"}]'::jsonb, 'исходники/карты/monika_card_39.png', 'swamp', false),
  (6, 'Радужное партнёрство', 'Вперёд! Раз когда мы или твой партнёр сыграете Радужное заклинание способность О бо время двоего хода, враг например может скомандовать его и выбрать любую цель.', 'special', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/monika_card_6.png', 'rainbow', true),
  (7, 'Дворец топи', 'Твоё Существо на этой линии получает +3 ATK. В начале каждого своего хода, сбрось карту.', 'здание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/monika_card_7.png', 'swamp', false),
  (8, 'Синхронизация', 'В начале фазы сражений твоей ты можешь терпнера, если ты или твоего партнера, отдав партнер не отдал заклиная в этом ход, отдай партнер может бесплатно сыграть заклинанце отомостью 1 или менее.', 'special', 1, 2, 1, false, '', '[{"trigger":"conditional","actions":[{"type":"play_for_free","target":"any","cost_filter":null,"source_text":"отдай партнер может бесплатно сыграть заклинанце отомостью 1 или менее"}],"conditions":[{"type":"if","description":"ты или твоего партнера"}],"description":"отдав партнер не отдал заклиная в этом ход, отдай партнер может бесплатно сыграть заклинанце отомостью 1 или менее","source_text":"если ты или твоего партнера, отдав партнер не отдал заклиная в этом ход, отдай партнер может бесплатно сыграть заклинанце отомостью 1 или менее"}]'::jsonb, 'исходники/карты/monika_card_8.png', 'swamp', false),
  (9, 'Ледяная база', 'Когда ледяная база вступает в игру, заморозь обе земли на этой линии. Можешь играть существо на эту землю даже если она заморожена.', 'здание', 1, NULL, 2, false, '', '[{"trigger":"on_enters_play","actions":[{"type":"freeze_landscape","target":"this_landscape_pair"}],"conditions":[],"description":"заморозь обе земли на этой линии","source_text":"Когда ледяная база вступает в игру, заморозь обе земли на этой линии"}]'::jsonb, 'исходники/карты/monika_card_9.png', 'ice', false),
  (1, 'Хлопковый великан', 'Если у Хлопкового великана осталось 3 DEF или меньше, его ATK увеличивается в 2 раза.', 'существо', 2, 2, 10, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"его ATK увеличивается в 2 раза"}],"conditions":[{"type":"if","description":"у Хлопкового великана осталось 3 DEF или меньше"}],"description":"его ATK увеличивается в 2 раза","source_text":"Если у Хлопкового великана осталось 3 DEF или меньше, его ATK увеличивается в 2 раза"}]'::jsonb, 'исходники/карты/tree_trunks_card_1.png', 'cute', false),
  (11, 'Громкий Бух', 'Приём >>> Самоподрыв. В начале твоего следующего хода взорвёмся, нанеся 6 урона существу противника на этой линии или противнику, если линия пуста. Если убьют во время хода противника, не взрывается. После самоподрыва сбрось его.', 'существо', 1, 1, 4, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"не взрывается"}],"conditions":[{"type":"if","description":"убьют во время хода противника"}],"description":"не взрывается","source_text":"Если убьют во время хода противника, не взрывается"}]'::jsonb, 'исходники/карты/tree_trunks_card_11.png', 'cute', false),
  (12, 'Взрывной мужик', 'Приём >>> нанеси 1 Урон существу противника перед собой и еще двум существам по бокам от него.', 'существо', 1, 2, 6, false, '', '[]'::jsonb, 'исходники/карты/tree_trunks_card_12.png', 'cute', false),
  (15, 'Перегоревший', 'Он очень зол.', 'существо', 1, 4, 2, false, '', '[]'::jsonb, 'исходники/карты/tree_trunks_card_15.png', 'cute', false),
  (16, 'Берсеркорова', 'Убивая существо, положи его карту под Берсеркорову, чтобы получить навсегда +1 АТК. Скинь все карты, если Берсеркорова выходит из игры.', 'существо', 2, 2, 9, false, '', '[]'::jsonb, 'исходники/карты/tree_trunks_card_16.png', 'cute', false),
  (18, 'Малыш каменепух', 'Если на поле присутствует Мамуля каменепух под твоим контролем, при защите Малыш получает +2 ATK.', 'существо', 1, 1, 7, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"при защите Малыш получает +2 ATK"}],"conditions":[{"type":"if","description":"на поле присутствует Мамуля каменепух под твоим контролем"}],"description":"при защите Малыш получает +2 ATK","source_text":"Если на поле присутствует Мамуля каменепух под твоим контролем, при защите Малыш получает +2 ATK"}]'::jsonb, 'исходники/карты/tree_trunks_card_18.png', 'cute', false),
  (19, 'Малыш камнепух', 'Если на поле присутствует Мамуля камнепух под твоим контролем, при защите Малыш получает +2 ATK.', 'существо', 1, 1, 7, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"при защите Малыш получает +2 ATK"}],"conditions":[{"type":"if","description":"на поле присутствует Мамуля камнепух под твоим контролем"}],"description":"при защите Малыш получает +2 ATK","source_text":"Если на поле присутствует Мамуля камнепух под твоим контролем, при защите Малыш получает +2 ATK"}]'::jsonb, 'исходники/карты/tree_trunks_card_19.png', 'cute', false),
  (2, 'Хлопковая гвардия', 'Укротитель: +1 ATK против существ со стоимостью ровно 2.', 'существо', 1, 2, 6, false, '', '[]'::jsonb, 'исходники/карты/tree_trunks_card_2.png', 'cute', false),
  (20, 'Мамуля камнепух', 'Если на поле присутствует Малыш камнепух под твоим контролем, Мамуля получает +1 АТК за каждого.', 'существо', 2, 3, 7, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"Мамуля получает +1 АТК за каждого"}],"conditions":[{"type":"if","description":"на поле присутствует Малыш камнепух под твоим контролем"}],"description":"Мамуля получает +1 АТК за каждого","source_text":"Если на поле присутствует Малыш камнепух под твоим контролем, Мамуля получает +1 АТК за каждого"}]'::jsonb, 'исходники/карты/tree_trunks_card_20.png', 'cute', false),
  (21, 'Абрака-милиус', 'Восстанови себе до 3 жизней, после чего распредели то же количество урона на своих существах на твой выбор.', 'заклинание', 0, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Восстанови","target":"none","effect":"себе до 3 жизней, после чего распредели то же количество урона на своих существах на твой выбор"}],"conditions":[{"type":"verb","value":"Восстанови"}],"description":"себе до 3 жизней, после чего распредели то же количество урона на своих существах на твой выбор","source_text":"Восстанови себе до 3 жизней, после чего распредели то же количество урона на своих существах на твой выбор"}]'::jsonb, 'исходники/карты/tree_trunks_card_21.png', 'cute', false),
  (24, 'Пуф!', 'Выбранному существу противника наносится урон, равный половине его максимальной DEF. Если показатель DEF нечётный, округляй вверх.', 'заклинание', 1, NULL, NULL, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"округляй вверх"}],"conditions":[{"type":"if","description":"показатель DEF нечётный"}],"description":"округляй вверх","source_text":"Если показатель DEF нечётный, округляй вверх"}]'::jsonb, 'исходники/карты/tree_trunks_card_24.png', 'cute', false),
  (25, 'Все или ничего', 'Ты сбрасываешь всех существ из игры и все карты с руки. После этого тяни 5 карт из колоды. У тебя есть 3 действия на то, чтобы сыграть существ, которые тебе выпали. Если существ не оказалось - готовься к худшему.', 'заклинание', 2, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/tree_trunks_card_25.png', 'cute', true),
  (26, 'Хлопковая аллея', 'Приём >>> Если у тебя под контролем одна аллея, можешь переместить существо на этой линии на пустую соседнюю землю. Если две, можешь также переместиться ко второй аллее или поменять местами существ, находящихся на землях с аллеей.', 'landscape', 1, NULL, NULL, false, '', '[{"trigger":"conditional","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[{"type":"if","description":"у тебя под контролем одна аллея"}],"description":"можешь переместить существо на этой линии на пустую соседнюю землю","source_text":"Если у тебя под контролем одна аллея, можешь переместить существо на этой линии на пустую соседнюю землю"},{"trigger":"conditional","actions":[{"type":"move","target":"chosen_creature","destination":"this_lane"}],"conditions":[{"type":"if","description":"две"}],"description":"можешь также переместиться ко второй аллее или поменять местами существ, находящихся на землях с аллеей","source_text":"Если две, можешь также переместиться ко второй аллее или поменять местами существ, находящихся на землях с аллеей"}]'::jsonb, 'исходники/карты/tree_trunks_card_26.png', 'cute', false),
  (29, 'Котячья Девятка', 'Каждый раз после того, как существо противника наносит Котячьей Девятке урон, можешь переместить её на пустую соседнюю землю.', 'существо', 1, 2, 4, false, '', '[]'::jsonb, 'исходники/карты/tree_trunks_card_29.png', 'rainbow', false),
  (30, 'Хлопковая няшка', 'Считается одновременно милым и радужным существом.', 'существо', 0, 1, 5, false, '', '[]'::jsonb, 'исходники/карты/tree_trunks_card_30.png', 'rainbow', true),
  (32, 'Сладкий пирожочек', 'Стоит на 1 действие меньше за каждое другое существо в игре под твоим контролем.
Прием >>> Пирожмяк: нанеси 2 урона существу, у которого осталось меньше всего DEF и ещё 1 - тому, у которого больше всего.', 'существо', 4, 0, 8, false, '', '[{"trigger":"manual","actions":[{"type":"deal_damage","target":"none","amount":2,"pierce":false}],"conditions":[{"type":"cost_actions","value":1}],"description":"Пирожмяк: нанеси 2 урона существу, у которого осталось меньше всего DEF и ещё 1 - тому, у которого больше все","source_text":"Прием >>> Пирожмяк: нанеси 2 урона существу, у которого осталось меньше всего DEF и ещё 1 - тому, у которого больше все"}]'::jsonb, 'исходники/карты/tree_trunks_card_32.png', 'rainbow', true),
  (33, 'Коробушка', 'Ей просто норм. +2 DEF и +1 ATK, если на поле присутствует Берсеркорова под твоим контролем.', 'существо', 0, 1, 3, false, '', '[]'::jsonb, 'исходники/карты/tree_trunks_card_33.png', 'rainbow', true),
  (34, 'Коровушка', 'Ей просто норм. +2 DEF и +1 ATK, если на поле присутствует Берсеркорова под твоим контролем.', 'существо', 0, 1, 3, false, '', '[]'::jsonb, 'исходники/карты/tree_trunks_card_34.png', 'rainbow', true),
  (35, 'Хлопковый форт', 'Хлопковые существа на этой линии под твоим контролем получают +1 ATK и +1 DEF.', 'здание', 1, NULL, NULL, false, '', '[]'::jsonb, 'исходники/карты/tree_trunks_card_35.png', 'cute', false),
  (37, 'Фонтан милашности', 'Восстанови себе 2 жизни (но не более 25) за каждое уничтоженное существо под твоим контролем на этой линии.', 'здание', 0, NULL, NULL, false, '', '[{"trigger":"manual","actions":[{"type":"imperative","verb":"Восстанови","target":"none","effect":"себе 2 жизни (но не более 25) за каждое уничтоженное существо под твоим контролем на этой линии"}],"conditions":[{"type":"verb","value":"Восстанови"}],"description":"себе 2 жизни (но не более 25) за каждое уничтоженное существо под твоим контролем на этой линии","source_text":"Восстанови себе 2 жизни (но не более 25) за каждое уничтоженное существо под твоим контролем на этой линии"}]'::jsonb, 'исходники/карты/tree_trunks_card_37.png', 'rainbow', false),
  (38, 'Милострах', 'Держись! Если у тебя 5 жизней игрока или меньше и ты сейчас получишь урон, милострах получает урон за тебя вне зависимости от того, на какой линии находится. Если атакует существо, он даёт ему сдачу, иначе просто получает урон.', 'существо', 2, 2, 8, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"милострах получает урон за тебя вне зависимости от того, на какой линии находится"}],"conditions":[{"type":"if","description":"у тебя 5 жизней игрока или меньше и ты сейчас получишь урон"}],"description":"милострах получает урон за тебя вне зависимости от того, на какой линии находится","source_text":"Если у тебя 5 жизней игрока или меньше и ты сейчас получишь урон, милострах получает урон за тебя вне зависимости от того, на какой линии находится"},{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"он даёт ему сдачу, иначе просто получает урон"}],"conditions":[{"type":"if","description":"атакует существо"}],"description":"он даёт ему сдачу, иначе просто получает урон","source_text":"Если атакует существо, он даёт ему сдачу, иначе просто получает урон"}]'::jsonb, 'исходники/карты/tree_trunks_card_38.png', 'cute', false),
  (39, 'Милая сладишка', '"Не бейте меня, пожалуйста!" Приём >>> Если у тебя 10 жизней или больше, +1 АТК любому существу в игре на этом ход, иначе +3. Не суммируется с приемами.', 'существо', 1, 0, 5, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"+1 АТК любому существу в игре на этом ход, иначе +3"}],"conditions":[{"type":"if","description":"у тебя 10 жизней или больше"}],"description":"+1 АТК любому существу в игре на этом ход, иначе +3","source_text":"Если у тебя 10 жизней или больше, +1 АТК любому существу в игре на этом ход, иначе +3"}]'::jsonb, 'исходники/карты/tree_trunks_card_39.png', 'cute', false),
  (4, 'Хлопковый король', '+1 DEF каждому хлопковому существу под твоим контролем, пока Король в игре. Прием >>> Вылечи существо под твоим контролем на 1 или 2 урона.', 'существо', 2, 2, 7, false, '', '[{"trigger":"manual","actions":[{"type":"manual","target":"none","effect":"Вылечи существо под твоим контролем на 1 или 2 уро"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Вылечи существо под твоим контролем на 1 или 2 уро","source_text":"Прием >>> Вылечи существо под твоим контролем на 1 или 2 уро"}]'::jsonb, 'исходники/карты/tree_trunks_card_4.png', 'cute', false),
  (40, 'Милая сладошка', '"Не бейте меня, пожалуйста!" Приём >>> Если у тебя 10 жизней или больше, +1 ATK любому существу в игре на этом ход, иначе +3. Не суммируется с приемами.', 'существо', 1, 0, 5, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"+1 ATK любому существу в игре на этом ход, иначе +3"}],"conditions":[{"type":"if","description":"у тебя 10 жизней или больше"}],"description":"+1 ATK любому существу в игре на этом ход, иначе +3","source_text":"Если у тебя 10 жизней или больше, +1 ATK любому существу в игре на этом ход, иначе +3"}]'::jsonb, 'исходники/карты/tree_trunks_card_40.png', 'cute', false),
  (7, 'Хлопковая Ведрыня', '+1 ATK против болотных и песчаных существ (Ведро!). Прием >>> Весь урон, который должны были получить другие союзные существа, получим она.', 'существо', 2, 1, 12, false, '', '[{"trigger":"manual","actions":[{"type":"manual","target":"none","effect":"Весь урон, который должны были получить другие союзные существа, получим о"}],"conditions":[{"type":"cost_actions","value":1}],"description":"Весь урон, который должны были получить другие союзные существа, получим о","source_text":"Прием >>> Весь урон, который должны были получить другие союзные существа, получим о"}]'::jsonb, 'исходники/карты/tree_trunks_card_7.png', 'cute', false),
  (8, 'Хлопковая лама', 'Приём >>> тяни карту. Если у Хлопковой ламы осталось 2 DEF или меньше, тяни две.', 'существо', 1, 2, 7, false, '', '[{"trigger":"conditional","actions":[{"type":"passive","target":"none","effect":"тяни две"}],"conditions":[{"type":"if","description":"у Хлопковой ламы осталось 2 DEF или меньше"}],"description":"тяни две","source_text":"Если у Хлопковой ламы осталось 2 DEF или меньше, тяни две"}]'::jsonb, 'исходники/карты/tree_trunks_card_8.png', 'cute', false);


